    def test_strategy_issue_recorders_attach_parameter_snapshot_to_audit_event(self) -> None:
        """Round 53 — strategy-issue audit events must carry the live parameter snapshot
        so auditors can see the effective parameters when the block fired."""

        control_main.repo.state.alerts = []

        strategy = next(
            item for item in control_main.repo.state.strategies if item.id == "trend-btc-01"
        )
        expected_snapshot = control_main.parameter_resolver.snapshot_parameters(strategy)
        # Seed strategy carries legacy parameter rows (fast_ma, slow_ma, ...) so the snapshot
        # must at least surface those — protects against future refactors that silently strip
        # keys from the canonical snapshot.
        self.assertIn("fast_ma", expected_snapshot)
        self.assertEqual(expected_snapshot["fast_ma"], 21)

        # Auto-dispatch issue recorder with explicit strategy kwarg.
        control_main._record_strategy_auto_dispatch_issue(
            strategy.id,
            strategy.name,
            strategy.symbols[0],
            "long",
            AccountMode.LIVE,
            "regression: ensure parameter_snapshot is attached on auto-dispatch block",
            strategy=strategy,
        )

        # Manual-execution recorder also carries the snapshot when strategy is supplied.
        control_main._record_strategy_manual_execution_issue(
            strategy.id,
            strategy.name,
            strategy.symbols[0],
            AccountMode.LIVE,
            "regression: ensure parameter_snapshot is attached on manual execution block",
            strategy=strategy,
        )

        # Without strategy context the snapshot must stay None — do NOT fabricate defaults.
        control_main._record_strategy_auto_dispatch_issue(
            strategy.id,
            strategy.name,
            strategy.symbols[0],
            "short",
            AccountMode.LIVE,
            "regression: ensure parameter_snapshot stays None when strategy is unknown",
        )

        audit_status, audit_events = self._get("/api/audit/events")
        self.assertEqual(audit_status, 200)

        auto_blocked_events = [
            item
            for item in audit_events
            if item["event_type"] == "strategy.exchange_order.auto_blocked"
            and item.get("strategy_id") == strategy.id
        ]
        self.assertEqual(len(auto_blocked_events), 2)

        with_strategy = next(
            item
            for item in auto_blocked_events
            if item["payload"].get("signal") == "long"
        )
        self.assertEqual(with_strategy["parameter_snapshot"], expected_snapshot)

        without_strategy = next(
            item
            for item in auto_blocked_events
            if item["payload"].get("signal") == "short"
        )
        self.assertIsNone(without_strategy["parameter_snapshot"])

        manual_blocked_event = next(
            item
            for item in audit_events
            if item["event_type"] == "strategy.execution.blocked"
            and item.get("strategy_id") == strategy.id
        )
        self.assertEqual(manual_blocked_event["parameter_snapshot"], expected_snapshot)

        manual_blocked_alerted_event = next(
            item
            for item in audit_events
            if item["event_type"] == "strategy.execution.blocked_alerted"
            and item.get("strategy_id") == strategy.id
        )
        self.assertEqual(manual_blocked_alerted_event["parameter_snapshot"], expected_snapshot)

    def test_exchange_order_lifecycle_events_attach_parameter_snapshot_for_strategy_orders(self) -> None:
        """Round 56 — exchange-order lifecycle events (created / cancelled /
        replaced) emitted for a strategy-attributed order must carry the same
        frozen parameter snapshot the auto-dispatch events already do, so the
        audit trail is bit-exact across the paper, live-dispatch, and direct
        exchange-lifecycle paths. Unknown / missing strategy stays None."""

        import parameter_resolver as _pr  # type: ignore  # noqa: PLC0415

        # Resolver returns None for the falsy / unknown cases.
        self.assertIsNone(control_main._resolve_strategy_parameter_snapshot(None))
        self.assertIsNone(control_main._resolve_strategy_parameter_snapshot(""))
        self.assertIsNone(control_main._resolve_strategy_parameter_snapshot("strategy-does-not-exist"))

        strategy = next(
            item for item in control_main.repo.state.strategies if item.id == "trend-btc-01"
        )
        expected_snapshot = _pr.snapshot_parameters(strategy)
        self.assertEqual(
            control_main._resolve_strategy_parameter_snapshot(strategy.id),
            expected_snapshot,
        )

        # Emit a representative strategy-attributed exchange-lifecycle event
        # through the repository's audit trail, exercising the kwarg surface
        # the Round-56 call sites now feed. We deliberately hit add_event
        # directly rather than spinning up the full private-trade stack so the
        # test stays focused on the snapshot plumbing contract.
        control_main.repo.add_event(
            event_type="exchange_order.created",
            source="quant-core",
            severity=control_main.EventSeverity.INFO,
            payload={
                "origin": "strategy",
                "strategy_id": strategy.id,
                "order_id": "round56-probe-001",
                "symbol": strategy.symbols[0],
            },
            symbol=strategy.symbols[0],
            strategy_id=strategy.id,
            parameter_snapshot=control_main._resolve_strategy_parameter_snapshot(strategy.id),
        )
        control_main.repo.add_event(
            event_type="exchange_order.created",
            source="quant-core",
            severity=control_main.EventSeverity.INFO,
            payload={
                "origin": "strategy",
                "strategy_id": "strategy-does-not-exist",
                "order_id": "round56-probe-unknown",
                "symbol": "BTCUSDT",
            },
            symbol="BTCUSDT",
            strategy_id="strategy-does-not-exist",
            parameter_snapshot=control_main._resolve_strategy_parameter_snapshot("strategy-does-not-exist"),
        )

        audit_status, audit_events = self._get("/api/audit/events")
        self.assertEqual(audit_status, 200)

        known_event = next(
            item
            for item in audit_events
            if item.get("payload", {}).get("order_id") == "round56-probe-001"
        )
        self.assertEqual(known_event["parameter_snapshot"], expected_snapshot)

        unknown_event = next(
            item
            for item in audit_events
            if item.get("payload", {}).get("order_id") == "round56-probe-unknown"
        )
        self.assertIsNone(unknown_event["parameter_snapshot"])

