        self.assertEqual(audit_status, 200)
        self.assertTrue(
            any(
                item["event_type"] == "exchange_order.rejected"
                and item["payload"].get("order_id") == "hist-live-strategy-rejected-001"
                for item in audit_events
            )
        )

