class StrategyParameterPatchRound49UnitTests(unittest.TestCase):
    """Round 49 — _apply_parameter_patch routes Round 44-47 top-level fields
    directly onto the strategy record; unknown keys continue to fall through
    to auxiliary StrategyParameter rows; BacktestRun.trades round-trips."""

    def setUp(self) -> None:
        self.strategy_id = "trend-btc-01"
        strategy = control_main.repo._find_strategy(self.strategy_id)
        self._snapshot = strategy.model_dump()

    def tearDown(self) -> None:
        from models import StrategySummary

        restored = StrategySummary.model_validate(self._snapshot)
        for idx, item in enumerate(control_main.repo.state.strategies):
            if item.id == self.strategy_id:
                control_main.repo.state.strategies[idx] = restored
                break

    def test_kernel_override_applied_to_top_level_field(self) -> None:
        control_main.repo._apply_parameter_patch(
            self.strategy_id,
            {"kernel": "momentum"},
        )
        strategy = control_main.repo._find_strategy(self.strategy_id)
        self.assertEqual(strategy.kernel, "momentum")
        self.assertFalse(any(p.key == "kernel" for p in strategy.parameters))

    def test_scalar_exit_tool_fields_applied(self) -> None:
        control_main.repo._apply_parameter_patch(
            self.strategy_id,
            {"trailing_stop_pct": 2.5, "break_even_trigger_pct": 1.0},
        )
        strategy = control_main.repo._find_strategy(self.strategy_id)
        self.assertEqual(strategy.trailing_stop_pct, 2.5)
        self.assertEqual(strategy.break_even_trigger_pct, 1.0)

    def test_nested_volatility_regime_thresholds_validated(self) -> None:
        control_main.repo._apply_parameter_patch(
            self.strategy_id,
            {"volatility_regime_thresholds": {"low_pct": 0.5, "high_pct": 2.0}},
        )
        strategy = control_main.repo._find_strategy(self.strategy_id)
        self.assertIsNotNone(strategy.volatility_regime_thresholds)
        self.assertEqual(strategy.volatility_regime_thresholds.low_pct, 0.5)
        self.assertEqual(strategy.volatility_regime_thresholds.high_pct, 2.0)

    def test_partial_take_profits_list_validated(self) -> None:
        control_main.repo._apply_parameter_patch(
            self.strategy_id,
            {
                "partial_take_profits": [
                    {"trigger_pct": 1.0, "exit_ratio": 0.5},
                    {"trigger_pct": 2.5, "exit_ratio": 0.5},
                ]
            },
        )
        strategy = control_main.repo._find_strategy(self.strategy_id)
        self.assertIsNotNone(strategy.partial_take_profits)
        self.assertEqual(len(strategy.partial_take_profits), 2)
        self.assertEqual(strategy.partial_take_profits[0].trigger_pct, 1.0)
        self.assertEqual(strategy.partial_take_profits[1].exit_ratio, 0.5)

    def test_regime_exposure_multipliers_validated(self) -> None:
        control_main.repo._apply_parameter_patch(
            self.strategy_id,
            {"regime_exposure_multipliers": {"low": 1.5, "normal": 1.0, "high": 0.4}},
        )
        strategy = control_main.repo._find_strategy(self.strategy_id)
        self.assertEqual(strategy.regime_exposure_multipliers.high, 0.4)

    def test_confidence_regime_adjustments_validated(self) -> None:
        control_main.repo._apply_parameter_patch(
            self.strategy_id,
            {"confidence_regime_adjustments": {"low": 1.1, "normal": 1.0, "high": 0.7}},
        )
        strategy = control_main.repo._find_strategy(self.strategy_id)
        self.assertEqual(strategy.confidence_regime_adjustments.low, 1.1)

    def test_invalid_kernel_raises(self) -> None:
        with self.assertRaises(ValueError):
            control_main.repo._apply_parameter_patch(
                self.strategy_id,
                {"kernel": "nonexistent_kernel"},
            )

    def test_unknown_key_falls_through_to_parameter_row(self) -> None:
        control_main.repo._apply_parameter_patch(
            self.strategy_id,
            {"custom_legacy_knob_round49": 123},
        )
        strategy = control_main.repo._find_strategy(self.strategy_id)
        self.assertTrue(any(p.key == "custom_legacy_knob_round49" for p in strategy.parameters))

    def test_backtest_run_trades_round_trip(self) -> None:
        from models import BacktestTradeModel

        trade_model = BacktestTradeModel.model_validate(
            {
                "entry_bar_index": 0,
                "exit_bar_index": 5,
                "entry_price": 100.0,
                "exit_price": 110.0,
                "quantity": 0.5,
                "side": "long",
                "volatility_regime": "low",
                "applied_risk_per_trade": 0.008,
            }
        )
        run = control_main.BacktestRun(
            id="bt-r49-test",
            strategy_id=self.strategy_id,
            strategy_name="Round 49 Test",
            status="completed",
            started_at="2026-04-20T00:00:00+08:00",
            symbol_scope=["BTCUSDT"],
            timeframe="1h",
            data_range="2026-01-01 ~ 2026-01-02",
            data_granularity="kline",
            fee_model="bybit-v5-standard",
            slippage_model="control-v1-adaptive",
            parameter_snapshot={},
            metrics=BacktestMetrics(
                annual_return="+10%",
                max_drawdown="-2%",
                sharpe="1.4",
                win_rate="55%",
                pnl="+1,000 USDT",
                trades=1,
            ),
            notes="round 49 trades round-trip",
            trades=[trade_model],
        )
        restored = control_main.BacktestRun.model_validate(run.model_dump())
        self.assertIsNotNone(restored.trades)
        self.assertEqual(len(restored.trades), 1)
        self.assertEqual(restored.trades[0].volatility_regime, "low")
        self.assertAlmostEqual(restored.trades[0].applied_risk_per_trade, 0.008)

    def test_backtest_run_legacy_no_trades_round_trip(self) -> None:
        run = control_main.BacktestRun(
            id="bt-r49-legacy",
            strategy_id=self.strategy_id,
            strategy_name="Round 49 Legacy",
            status="completed",
            started_at="2026-04-20T00:00:00+08:00",
            symbol_scope=["BTCUSDT"],
            timeframe="1h",
            data_range="2026-01-01 ~ 2026-01-02",
            data_granularity="kline",
            fee_model="bybit-v5-standard",
            slippage_model="control-v1-adaptive",
            parameter_snapshot={},
            metrics=BacktestMetrics(
                annual_return="0",
                max_drawdown="0",
                sharpe="0",
                win_rate="0",
                pnl="0",
                trades=0,
            ),
            notes="legacy",
        )
        restored = control_main.BacktestRun.model_validate(run.model_dump())
        self.assertIsNone(restored.trades)


class StrategyRuntimeTopLevelParamLookupRound50Tests(unittest.TestCase):
    """Round 50 — the runtime evaluator must prefer the Round 47/49 top-level
    scalar fields (``roc_window``, ``bollinger_window``, ``rsi_window``, etc.)
    over the legacy ``StrategyParameter`` rows. Until R50 the evaluator only
    looked at ``strategy.parameters`` which meant migrated strategies that
    moved these knobs to the top level silently kept the evaluator defaults.
    """

    def _momentum_strategy(self, **overrides: Any) -> Any:
        from models import StrategySummary

        base = dict(
            id="momentum-unit-01",
            name="MomentumR50",
            category="template",
            status="running",
            symbols=["BTCUSDT"],
            mode=AccountMode.PAPER,
            version="v1",
            pnl_7d="+0.0%",
            max_drawdown="-0.0%",
            risk_budget="10%",
            description="round50 runtime top-level lookup",
            parameters=[],
            kernel="momentum",
        )
        base.update(overrides)
        return StrategySummary(**base)

    def test_top_level_roc_window_overrides_default(self) -> None:
        from strategy_runtime import _param_value

        strategy = self._momentum_strategy(roc_window=7)
        self.assertEqual(_param_value(strategy, "roc_window", 10.0), 7.0)

    def test_top_level_none_falls_back_to_parameter_row(self) -> None:
        from strategy_runtime import _param_value

        strategy = self._momentum_strategy(
            roc_window=None,
            parameters=[StrategyParameter(key="roc_window", label="roc", value=5)],
        )
        self.assertEqual(_param_value(strategy, "roc_window", 10.0), 5.0)

    def test_top_level_and_parameter_both_present_top_level_wins(self) -> None:
        from strategy_runtime import _param_value

        strategy = self._momentum_strategy(
            roc_window=12,
            parameters=[StrategyParameter(key="roc_window", label="roc", value=99)],
        )
        self.assertEqual(_param_value(strategy, "roc_window", 10.0), 12.0)

    def test_default_returned_when_neither_source_has_value(self) -> None:
        from strategy_runtime import _param_value

        strategy = self._momentum_strategy(roc_window=None, parameters=[])
        self.assertEqual(_param_value(strategy, "roc_window", 10.0), 10.0)


class BacktestEngineTopLevelParameterMapRound50Tests(unittest.TestCase):
    """Round 50 — ``_parameter_map`` now overlays the Round 47/49 top-level
    kernel-tuning scalars on top of the legacy parameter list so the runners
    and the ``BacktestComputation.parameter_snapshot`` both see the migrated
    knobs. ``None`` top-level values skip the overlay so legacy payloads keep
    their bit-exact pre-R50 mapping.
    """

    def _strategy(self, **overrides: Any) -> Any:
        from models import StrategySummary

        base = dict(
            id="brk-top-level-01",
            name="TopLevelOverlay",
            category="template",
            status="running",
            symbols=["BTCUSDT"],
            mode=AccountMode.PAPER,
            version="v1",
            pnl_7d="+0.0%",
            max_drawdown="-0.0%",
            risk_budget="12%",
            description="round50 parameter overlay",
            parameters=[
                StrategyParameter(key="breakout_window", label="bw", value=5),
                StrategyParameter(key="max_hold_hours", label="mh", value=200),
            ],
        )
        base.update(overrides)
        return StrategySummary(**base)

    def test_top_level_fields_overlay_parameter_map(self) -> None:
        strategy = self._strategy(
            kernel="bollinger_squeeze",
            bollinger_window=24,
            bollinger_std=2.5,
            squeeze_bandwidth_pct=1.75,
        )
        mapping = backtest_engine._parameter_map(strategy)
        self.assertEqual(mapping["bollinger_window"], 24)
        self.assertEqual(mapping["bollinger_std"], 2.5)
        self.assertEqual(mapping["squeeze_bandwidth_pct"], 1.75)
        self.assertEqual(mapping["breakout_window"], 5)

    def test_none_top_level_fields_do_not_clobber_legacy_rows(self) -> None:
        # rsi_window stays on the parameter row; the top-level attribute
        # defaults to None, so the overlay must be a no-op for this key.
        strategy = self._strategy(
            parameters=[
                StrategyParameter(key="breakout_window", label="bw", value=5),
                StrategyParameter(key="rsi_window", label="rsi", value=21),
            ],
        )
        mapping = backtest_engine._parameter_map(strategy)
        self.assertEqual(mapping["rsi_window"], 21)

    def test_parameter_snapshot_includes_top_level_fields(self) -> None:
        strategy = self._strategy(
            kernel="momentum",
            roc_window=4,
            ema_trend_window=6,
            momentum_threshold_pct=0.5,
        )
        candles = [
            backtest_engine.CandlePoint(
                time=f"2026-01-{(idx % 28) + 1:02d}T{idx % 24:02d}:00:00+00:00",
                open=100.0 + idx,
                high=100.0 + idx,
                low=100.0 + idx,
                close=100.0 + idx,
                volume=1000.0,
            )
            for idx in range(30)
        ]
        result = backtest_engine.run_local_backtest(
            strategy,
            candles,
            "1h",
            "2026-01-01 ~ 2026-01-05",
        )
        self.assertEqual(result.parameter_snapshot["roc_window"], 4)
        self.assertEqual(result.parameter_snapshot["ema_trend_window"], 6)
        self.assertAlmostEqual(result.parameter_snapshot["momentum_threshold_pct"], 0.5)


class PartialTakeProfitTradeMetadataRound50Tests(unittest.TestCase):
    """Round 50 — partial take-profit trade records must inherit the original
    entry bar index and carry the volatility-regime / applied-risk metadata.
    Before R50 the helper stamped the current bar as the entry and dropped
    the regime / risk fields entirely, which skewed the holding-rhythm and
    per-regime aggregations that R48 surfaced in the UI.
    """

    BREAKOUT_WINDOW = 5
    BREAKOUT_BAR = 5

    def _strategy_with_partial_ladder(self) -> Any:
        from models import StrategySummary

        return StrategySummary(
            id="brk-partial-metadata-01",
            name="PartialTpMetadataR50",
            category="template",
            status="running",
            symbols=["BTCUSDT"],
            mode=AccountMode.PAPER,
            version="v1",
            pnl_7d="+0.0%",
            max_drawdown="-0.0%",
            risk_budget="18%",
            description="round50 partial tp metadata",
            parameters=[
                StrategyParameter(key="breakout_window", label="bw", value=self.BREAKOUT_WINDOW),
                StrategyParameter(key="volume_ratio", label="vr", value=1.0),
                StrategyParameter(key="max_hold_hours", label="mh", value=2000),
            ],
            partial_take_profits=[
                PartialTakeProfit(trigger_pct=1.0, exit_ratio=0.5),
                PartialTakeProfit(trigger_pct=2.5, exit_ratio=0.5),
            ],
        )

    def _candles(self, prices: List[float]) -> List[Any]:
        return [
            backtest_engine.CandlePoint(
                time=f"2026-01-{(index % 28) + 1:02d}T{index % 24:02d}:00:00+00:00",
                open=price,
                high=price,
                low=price,
                close=price,
                volume=1000.0 * (3.0 if index == self.BREAKOUT_BAR else 1.0),
            )
            for index, price in enumerate(prices)
        ]

    def test_partial_trade_inherits_original_entry_bar_index(self) -> None:
        strategy = self._strategy_with_partial_ladder()
        # Entry on bar 5 (breakout with 3x volume). Bar 6 prints 112 → rung 1
        # fires (pnl ~1.82%). Bar 7 prints 113 → rung 2 fires (pnl ~2.73%,
        # drains the ladder). Before R50 the partial trade would have
        # ``entry_bar_index == exit_bar_index``; after R50 it must inherit
        # the actual entry bar.
        candles = self._candles([100, 101, 102, 103, 104, 110, 112, 113])

        result = backtest_engine.run_local_backtest(
            strategy,
            candles,
            "1h",
            "2026-01-01 ~ 2026-01-05",
        )

        self.assertGreaterEqual(len(result.trades), 1)
        partial_trades = [trade for trade in result.trades if trade.exit_bar_index != trade.entry_bar_index]
        self.assertTrue(partial_trades, "expected at least one partial trade with entry != exit")
        for trade in partial_trades:
            self.assertEqual(
                trade.entry_bar_index,
                self.BREAKOUT_BAR,
                "partial trade must inherit the original entry bar",
            )
            self.assertGreater(trade.exit_bar_index, trade.entry_bar_index)

    def test_partial_trade_carries_regime_and_applied_risk_when_sizing_enabled(self) -> None:
        from models import RegimeExposureMultipliers, StrategySummary, VolatilityRegimeThresholds

        strategy = StrategySummary(
            id="brk-partial-regime-01",
            name="PartialTpRegimeR50",
            category="template",
            status="running",
            symbols=["BTCUSDT"],
            mode=AccountMode.PAPER,
            version="v1",
            pnl_7d="+0.0%",
            max_drawdown="-0.0%",
            risk_budget="18%",
            description="round50 partial tp regime",
            parameters=[
                StrategyParameter(key="breakout_window", label="bw", value=self.BREAKOUT_WINDOW),
                StrategyParameter(key="volume_ratio", label="vr", value=1.0),
                StrategyParameter(key="max_hold_hours", label="mh", value=2000),
            ],
            partial_take_profits=[PartialTakeProfit(trigger_pct=1.0, exit_ratio=0.5)],
            volatility_sizing_enabled=True,
            volatility_lookback=3,
            volatility_regime_thresholds=VolatilityRegimeThresholds(low_pct=0.0, high_pct=100.0),
            regime_exposure_multipliers=RegimeExposureMultipliers(low=1.0, normal=1.0, high=1.0),
        )
        candles = self._candles([100, 101, 102, 103, 104, 110, 112, 113])

        result = backtest_engine.run_local_backtest(
            strategy,
            candles,
            "1h",
            "2026-01-01 ~ 2026-01-05",
        )

        partial_trades = [trade for trade in result.trades if trade.exit_bar_index != trade.entry_bar_index]
        self.assertTrue(partial_trades)
        for trade in partial_trades:
            self.assertIsNotNone(trade.volatility_regime)
            self.assertIsNotNone(trade.applied_risk_per_trade)


class RiskDecisionRound58UnitTests(unittest.TestCase):
    """Round 58 — structured :class:`RiskDecision` wrapper regression suite.

    Asserts the four pieces of the new typing surface:

    * ``RiskDecision`` accepts the documented verdict enum + reason code and
      survives a pydantic JSON round-trip.
    * The ``allow``-path mapping returns ``verdict="allow"`` with
      ``reason_code="risk.approved"``.
    * The ``block``-path mapping returns ``verdict="block"`` with a stable
      ``reason_code`` derived from today's free-form ``blocked_reason`` text.
    * Old callers that still inspect numeric fields keep working through the
      embedded ``decision.preview`` —  this is the compatibility contract we
      promised when introducing the wrapper.
    """

    @staticmethod
    def _build_preview(
        *,
        allowed: bool,
        blocked_reason: Optional[str] = None,
        warnings: Optional[List[str]] = None,
        recommended_action: Optional[str] = None,
    ):
        """Return a minimal ``ExecutionPreview`` tailored for this suite.

        All numeric fields are filled with concrete values so the
        compatibility test below can assert the embedded preview still
        exposes them verbatim.
        """

        from models import ExecutionPreview  # type: ignore  # noqa: E402

        return ExecutionPreview(
            symbol="BTCUSDT",
            market="perp",
            mode=AccountMode.PAPER,
            side=Direction.BUY,
            origin="manual",
            quantity=0.5,
            price=42_000.0,
            notional="21000.00",
            action="开多",
            allowed=allowed,
            blocked_reason=blocked_reason,
            recommended_action=recommended_action,
            warnings=list(warnings or []),
            current_position_size="0",
            current_avg_price="--",
            projected_position_size="0.5",
            projected_avg_price="42000.00",
            available_balance_before="50000.00",
            available_balance_after="29000.00",
            estimated_realized_pnl="--",
            generated_at="2026-04-21T08:00:00+08:00",
        )

    def test_risk_decision_model_round_trips_verdict_and_reason_code(self) -> None:
        """The pydantic model must accept the documented verdict literal +
        machine-readable ``reason_code`` and survive a JSON round-trip so
        downstream services can persist decisions to audit stores without
        losing structure."""

        from models import RiskDecision  # type: ignore  # noqa: E402

        preview = self._build_preview(allowed=True)
        decision = RiskDecision(
            verdict="degrade",
            reason_code="risk.exposure_cap",
            reason_detail="当前敞口已接近上限，建议按 50% 规模继续。",
            recommended_action={"size_multiplier": 0.5},
            preview=preview,
        )

        self.assertEqual(decision.verdict, "degrade")
        self.assertEqual(decision.reason_code, "risk.exposure_cap")
        assert decision.recommended_action is not None
        # Round 73 — ``recommended_action`` is now the typed
        # :class:`RiskDecisionRecommendation`; attribute access replaces the
        # old ``.get("size_multiplier")`` dict-style read.  Pydantic coerces
        # the dict argument above into the model transparently.
        self.assertEqual(decision.recommended_action.size_multiplier, 0.5)
        self.assertIsNotNone(decision.timestamp)

        payload = decision.model_dump_json()
        restored = RiskDecision.model_validate_json(payload)
        self.assertEqual(restored.verdict, "degrade")
        self.assertEqual(restored.reason_code, "risk.exposure_cap")
        self.assertEqual(restored.reason_detail, decision.reason_detail)
        self.assertEqual(restored.preview.symbol, preview.symbol)

    def test_evaluate_risk_decision_allow_path_returns_allow_verdict(self) -> None:
        """An ``ExecutionPreview`` with ``allowed=True`` must map to a
        ``verdict="allow"`` decision carrying the ``risk.approved`` code —
        this is the happy-path contract the dispatcher relies on to branch."""

        import risk_decision  # type: ignore  # noqa: E402
        from models import RISK_REASON_APPROVED  # type: ignore  # noqa: E402

        preview = self._build_preview(allowed=True)

        decision = risk_decision.evaluate_risk_decision(preview)

        self.assertEqual(decision.verdict, "allow")
        self.assertEqual(decision.reason_code, RISK_REASON_APPROVED)
        self.assertIs(decision.preview, preview)

    def test_evaluate_risk_decision_block_path_maps_insufficient_balance(
        self,
    ) -> None:
        """When the preview is blocked for balance reasons the wrapper must
        emit ``verdict="block"`` with the stable
        ``risk.insufficient_balance`` code — so callers can stop substring-
        matching on Chinese strings like ``"可用余额不足"``."""

        import risk_decision  # type: ignore  # noqa: E402
        from models import RISK_REASON_INSUFFICIENT_BALANCE  # type: ignore  # noqa: E402

        preview = self._build_preview(
            allowed=False,
            blocked_reason="当前 Paper 可用余额不足，缺口 2000 USDT。",
            recommended_action="请先补充 Paper 可用余额。",
        )

        decision = risk_decision.evaluate_risk_decision(preview)

        self.assertEqual(decision.verdict, "block")
        self.assertEqual(decision.reason_code, RISK_REASON_INSUFFICIENT_BALANCE)
        self.assertIn("可用余额不足", decision.reason_detail)
        assert decision.recommended_action is not None
        self.assertEqual(
            decision.recommended_action.recommendation,
            "请先补充 Paper 可用余额。",
        )

    def test_embedded_preview_keeps_numeric_fields_readable(self) -> None:
        """Old callers that read numeric fields off the preview must keep
        working through ``decision.preview`` — this is the backward-compat
        contract the wrapper commits to.  Without it the structural refactor
        would silently break every downstream consumer."""

        import risk_decision  # type: ignore  # noqa: E402

        preview = self._build_preview(allowed=True)

        decision = risk_decision.evaluate_risk_decision(preview)

        # Numeric-ish fields that today's callers read off the preview:
        self.assertEqual(decision.preview.quantity, 0.5)
        self.assertEqual(decision.preview.price, 42_000.0)
        self.assertEqual(decision.preview.notional, "21000.00")
        self.assertEqual(decision.preview.projected_position_size, "0.5")
        self.assertEqual(decision.preview.available_balance_before, "50000.00")
        self.assertEqual(decision.preview.available_balance_after, "29000.00")
        # And structural fields such as the rendered action label:
        self.assertEqual(decision.preview.action, "开多")


class ExecutionIntentRound57UnitTests(unittest.TestCase):
    """Round 57 — ``ExecutionIntent`` is the canonical hand-off between the
    two strategy-signal entry points (manual REST / autonomous worker) and
    the paper + live dispatcher branches.  These tests freeze two load-bearing
    invariants so future refactors cannot silently drift:

    * ``_classify_execution_intent_source`` discriminator — the source label
      must be ``"auto"`` iff ``requested_by`` is the sentinel
      ``"strategy_runtime_worker"``, regardless of surrounding whitespace.
      A drift here would mis-attribute autonomous fills as operator-issued
      on downstream audit surfaces.
    * ``_build_execution_intent_from_state`` factory — the frozen intent
      must reflect ``preview``'s numeric fields (side / quantity / price) so
      the dispatcher cannot re-derive stale values from the live snapshot,
      and the ``parameter_snapshot`` must match
      ``parameter_resolver.snapshot_parameters(strategy)`` byte-for-byte so
      the R51+ audit emissions keep agreeing with the runtime evaluator.
    """

    def _make_strategy(self, **overrides: Any) -> Any:
        from models import StrategySummary

        base: Dict[str, Any] = dict(
            id="intent-r57-01",
            name="ExecutionIntentHarness",
            category="template",
            status="running",
            symbols=["BTCUSDT"],
            mode=AccountMode.PAPER,
            version="v1",
            pnl_7d="+0.0%",
            max_drawdown="-0.0%",
            risk_budget="10%",
            description="Round 57 ExecutionIntent harness",
            parameters=[StrategyParameter(key="fast_ma", label="fast", value=21)],
            kernel="momentum",
            roc_window=9,
            ema_trend_window=13,
        )
        base.update(overrides)
        return StrategySummary(**base)

    def _make_snapshot(self, strategy: Any, **overrides: Any) -> StrategyRuntimeSnapshot:
        base: Dict[str, Any] = dict(
            strategy_id=strategy.id,
            strategy_name=strategy.name,
            symbol="BTCUSDT",
            market="perp",
            mode=strategy.mode,
            runtime_status="running",
            signal="long",
            confidence=0.72,
            last_price=42_100.0,
            reference_price=42_050.0,
            change_24h=0.012,
            note="R57 harness snapshot",
            next_action="按信号执行",
            last_evaluated_at="2026-04-21T08:00:00+08:00",
        )
        base.update(overrides)
        return StrategyRuntimeSnapshot(**base)

    def _make_preview(
        self,
        *,
        allowed: bool = True,
        side: Direction = Direction.BUY,
        quantity: float = 0.25,
        price: float = 42_100.0,
    ):
        from models import ExecutionPreview

        return ExecutionPreview(
            symbol="BTCUSDT",
            market="perp",
            mode=AccountMode.PAPER,
            side=side,
            origin="strategy",
            quantity=quantity,
            price=price,
            notional="10525.00",
            action="开多",
            allowed=allowed,
            blocked_reason=None,
            recommended_action=None,
            warnings=[],
            current_position_size="0",
            current_avg_price="--",
            projected_position_size=str(quantity),
            projected_avg_price=str(price),
            available_balance_before="50000.00",
            available_balance_after="39475.00",
            estimated_realized_pnl="--",
            generated_at="2026-04-21T08:00:00+08:00",
        )

    def test_classify_execution_intent_source_distinguishes_auto_vs_manual(self) -> None:
        """The discriminator must tag autonomous dispatches as ``"auto"`` and
        every other requester (desktop operator, REST "Execute" button, etc.)
        as ``"manual"`` — whitespace-only / empty ``requested_by`` also
        collapses to ``"manual"`` since nothing claims to be the runtime
        worker.  Without this invariant, audit surfaces (``source`` label on
        emitted events, parameter-snapshot attribution) cannot reliably tell
        which entry point originated a fill.
        """

        from models import StrategyExecutionRequest

        auto = StrategyExecutionRequest(requested_by="strategy_runtime_worker")
        self.assertEqual(
            control_main._classify_execution_intent_source(auto),
            "auto",
        )
        padded_auto = StrategyExecutionRequest(requested_by="  strategy_runtime_worker  ")
        self.assertEqual(
            control_main._classify_execution_intent_source(padded_auto),
            "auto",
        )

        manual = StrategyExecutionRequest(requested_by="desktop_operator")
        self.assertEqual(
            control_main._classify_execution_intent_source(manual),
            "manual",
        )
        empty = StrategyExecutionRequest(requested_by="")
        self.assertEqual(
            control_main._classify_execution_intent_source(empty),
            "manual",
        )
        whitespace = StrategyExecutionRequest(requested_by="   ")
        self.assertEqual(
            control_main._classify_execution_intent_source(whitespace),
            "manual",
        )

    def test_build_execution_intent_from_state_freezes_preview_and_parameter_snapshot(self) -> None:
        """The factory must copy numeric fields from ``preview`` (not from the
        live snapshot, which could drift mid-dispatch), route the snapshot
        through :mod:`parameter_resolver` so R51+ audit emissions agree with
        the runtime evaluator, and surface the R58 ``RiskDecision`` verdict
        verbatim.
        """

        import parameter_resolver as param_resolver
        from models import StrategyExecutionRequest
        from risk_decision import evaluate_risk_decision

        strategy = self._make_strategy()
        snapshot = self._make_snapshot(strategy)
        preview = self._make_preview(
            side=Direction.SELL,
            quantity=0.375,
            price=41_900.0,
        )
        decision = evaluate_risk_decision(preview)
        payload = StrategyExecutionRequest(
            requested_by="strategy_runtime_worker",
            note="R57 自动执行",
            mode=AccountMode.PAPER,
        )

        intent = control_main._build_execution_intent_from_state(
            strategy_id=strategy.id,
            payload=payload,
            strategy=strategy,
            snapshot=snapshot,
            resolved_mode=AccountMode.PAPER,
            preview=preview,
            decision=decision,
        )

        self.assertEqual(intent.strategy_id, strategy.id)
        self.assertEqual(intent.strategy_name, strategy.name)
        self.assertEqual(intent.source, "auto")
        self.assertEqual(intent.mode, AccountMode.PAPER)
        self.assertEqual(intent.symbol, snapshot.symbol)
        self.assertEqual(intent.market, snapshot.market)
        self.assertEqual(intent.signal, snapshot.signal)
        self.assertEqual(intent.requested_by, payload.requested_by)
        self.assertEqual(intent.note, payload.note)
        # Numeric fields must mirror the preview the R58 decision evaluated:
        self.assertEqual(intent.side, preview.side)
        self.assertEqual(intent.quantity, preview.quantity)
        self.assertEqual(intent.price, preview.price)
        # Decision travels verbatim so the dispatcher never re-derives it:
        self.assertEqual(intent.decision.verdict, decision.verdict)
        self.assertEqual(intent.decision.reason_code, decision.reason_code)
        # Parameter snapshot must match parameter_resolver byte-for-byte so
        # the runtime evaluator, the backtest runner and the dispatcher all
        # see the same effective values (R51+ cross-site invariant).
        self.assertEqual(
            intent.parameter_snapshot,
            param_resolver.snapshot_parameters(strategy),
        )
        # ``kernel`` and the top-level scalars flow through the snapshot:
        self.assertEqual(intent.parameter_snapshot.get("kernel"), "momentum")
        self.assertEqual(intent.parameter_snapshot.get("roc_window"), 9)
        self.assertEqual(intent.parameter_snapshot.get("ema_trend_window"), 13)
        # Legacy parameter rows merge in alongside top-level scalars:
        self.assertEqual(intent.parameter_snapshot.get("fast_ma"), 21)


class LiveOrderReconciliationRound59UnitTests(unittest.TestCase):
    """Round 59 — ``LiveOrderReconciliation`` + ``_classify_live_order_reconciliation``
    regression suite.

    Before R59 the reuse / amend / submit decision was interleaved with side
    effects inside ``_dispatch_live_intent``, so the branching couldn't be
    asserted without the full runtime stack.  The classifier is now a pure
    function whose typed decision is frozen here against four invariants:

    * **submit** — no existing order on the requested side (stale orders on
      the opposite side are still surfaced for cancellation).
    * **reuse** — existing order matches target on quantity + price (and
      ``reduce_only`` when required).
    * **amend (numeric)** — existing order differs on quantity or price.
    * **amend (reduce_only)** — existing order matches on qty + price but
      lacks the ``reduce_only`` flag that the preview requires.
    """

    def _order(
        self,
        *,
        order_id: str,
        side: Direction = Direction.BUY,
        qty: str = "0.25",
        price: str = "42100.00",
    ):
        from models import OrderRecord

        return OrderRecord(
            source="bybit_private",
            origin="strategy",
            strategy_id="intent-r59-01",
            order_id=order_id,
            symbol="BTCUSDT",
            market="perp",
            side=side,
            order_type="limit",
            qty=qty,
            price=price,
            status="new",
            created_at="2026-04-22T08:00:00+08:00",
        )

    def _intent(
        self,
        *,
        side: Direction = Direction.BUY,
        quantity: float = 0.25,
        price: float = 42_100.0,
    ):
        from models import (
            ExecutionIntent,
            ExecutionPreview,
        )
        from risk_decision import evaluate_risk_decision

        preview = ExecutionPreview(
            symbol="BTCUSDT",
            market="perp",
            mode=AccountMode.LIVE,
            side=side,
            origin="strategy",
            quantity=quantity,
            price=price,
            notional=f"{quantity * price:.2f}",
            action="开多" if side == Direction.BUY else "开空",
            allowed=True,
            warnings=[],
            current_position_size="0",
            current_avg_price="--",
            projected_position_size=str(quantity),
            projected_avg_price=str(price),
            available_balance_before="50000.00",
            available_balance_after="39475.00",
            estimated_realized_pnl="--",
            generated_at="2026-04-22T08:00:00+08:00",
        )
        return ExecutionIntent(
            strategy_id="intent-r59-01",
            strategy_name="ReconHarness",
            source="auto",
            mode=AccountMode.LIVE,
            symbol="BTCUSDT",
            market="perp",
            side=side,
            quantity=quantity,
            price=price,
            signal="long",
            preview=preview,
            decision=evaluate_risk_decision(preview),
            parameter_snapshot={},
            requested_by="strategy_runtime_worker",
            note=None,
            created_at="2026-04-22T08:00:00+08:00",
        )

    def test_submit_when_no_matching_order_exists(self) -> None:
        """An empty order book surfaces as ``action="submit"`` with the
        ``order.no_existing_match`` reason; opposite-side orders are carried
        through as stale so the dispatcher cancels them before submit.
        """

        intent = self._intent(side=Direction.BUY)
        opposite = self._order(order_id="opp-01", side=Direction.SELL)

        recon = control_main._classify_live_order_reconciliation(
            intent, [opposite], requires_reduce_only=False,
        )

        self.assertEqual(recon.action, "submit")
        self.assertEqual(recon.reason_code, "order.no_existing_match")
        self.assertIsNone(recon.matching_order)
        self.assertEqual([o.order_id for o in recon.stale_orders], ["opp-01"])

    def test_reuse_when_matching_order_matches_target(self) -> None:
        """A same-side order whose qty + price match the intent surfaces as
        ``action="reuse"`` with reason ``order.matches_target``.  Any
        opposite-side orders are kept as stale for cancellation.
        """

        intent = self._intent(side=Direction.BUY, quantity=0.25, price=42_100.0)
        matching = self._order(order_id="match-01", side=Direction.BUY, qty="0.25", price="42100.00")
        opposite = self._order(order_id="opp-01", side=Direction.SELL)

        recon = control_main._classify_live_order_reconciliation(
            intent, [matching, opposite], requires_reduce_only=False,
        )

        self.assertEqual(recon.action, "reuse")
        self.assertEqual(recon.reason_code, "order.matches_target")
        assert recon.matching_order is not None
        self.assertEqual(recon.matching_order.order_id, "match-01")
        self.assertEqual([o.order_id for o in recon.stale_orders], ["opp-01"])

    def test_amend_with_numeric_reason_when_quantity_or_price_differs(self) -> None:
        """A same-side order that differs on quantity (or price) surfaces as
        ``action="amend"`` with reason ``order.differs_numeric``.
        """

        intent = self._intent(side=Direction.BUY, quantity=0.25, price=42_100.0)
        # quantity differs (0.50 vs 0.25)
        diff_qty = self._order(order_id="amend-qty", side=Direction.BUY, qty="0.50", price="42100.00")

        recon = control_main._classify_live_order_reconciliation(
            intent, [diff_qty], requires_reduce_only=False,
        )

        self.assertEqual(recon.action, "amend")
        self.assertEqual(recon.reason_code, "order.differs_numeric")
        assert recon.matching_order is not None
        self.assertEqual(recon.matching_order.order_id, "amend-qty")

    def test_amend_with_reduce_only_reason_when_flag_required_but_absent(self) -> None:
        """When qty + price match but the preview requires ``reduce_only`` and
        the underlying private order lacks the flag,
        ``_exchange_order_matches_requested_target`` returns False and the
        classifier must surface reason ``order.requires_reduce_only`` so the
        audit trail can distinguish a flag toggle from a true numeric diff.
        """

        intent = self._intent(side=Direction.BUY, quantity=0.25, price=42_100.0)
        matching = self._order(order_id="match-reduce", side=Direction.BUY, qty="0.25", price="42100.00")

        # Patch the raw-private lookup so ``_exchange_order_matches_requested_target``
        # treats the matching order as lacking the reduce_only flag.
        with patch.object(control_main, "_find_private_raw_open_order", return_value=None), \
             patch.object(control_main, "_raw_private_order_reduce_only_enabled", return_value=False):
            recon = control_main._classify_live_order_reconciliation(
                intent, [matching], requires_reduce_only=True,
            )

        self.assertEqual(recon.action, "amend")
        self.assertEqual(recon.reason_code, "order.requires_reduce_only")
        assert recon.matching_order is not None
        self.assertEqual(recon.matching_order.order_id, "match-reduce")


class AutoDispatchGateRound60UnitTests(unittest.TestCase):
    """Round 60 — ``AutoDispatchGate`` + ``_evaluate_strategy_auto_dispatch_gate``
    regression suite.

    Before R60 the autonomous strategy-runtime worker used six
    ``continue``-style guards at the head of
    ``_auto_dispatch_strategy_signal_changes`` to interleave the
    "should we dispatch?" verdict with the side effects on block
    (cancel existing orders / clear auto-dispatch alerts / record an
    auto-dispatch issue).  The typed decision is now pinned here
    against the seven documented reason codes so future refactors
    cannot silently drift the gate shape:

    * ``auto.paper_or_paused_strategy`` — paper / shadow / paused.
    * ``auto.live_stop_loss_cooldown`` — cooldown minutes remaining.
    * ``auto.live_stop_loss_active`` — reference-price alert armed.
    * ``auto.rejection_guard_active`` — exchange-rejection cooldown.
    * ``auto.scheduler_or_channel_gate`` — scheduler paused / WS down.
    * ``auto.runtime_not_running`` — runtime in a non-running state.
    * ``auto.ready`` — all guards pass; intent is dispatchable.
    """

    def _strategy(
        self,
        *,
        mode: AccountMode = AccountMode.LIVE,
        status: str = "running",
    ):
        from models import StrategyParameter, StrategySummary

        return StrategySummary(
            id="gate-r60-01",
            name="GateHarness",
            category="template",
            status=status,
            symbols=["BTCUSDT"],
            mode=mode,
            version="v1",
            pnl_7d="+0.0%",
            max_drawdown="-0.0%",
            risk_budget="10%",
            description="R60 gate harness",
            parameters=[StrategyParameter(key="noop", label="noop", value=0.0)],
        )

    def _snapshot(self, *, runtime_status: str = "running"):
        return StrategyRuntimeSnapshot(
            strategy_id="gate-r60-01",
            strategy_name="GateHarness",
            symbol="BTCUSDT",
            market="perp",
            mode=AccountMode.LIVE,
            runtime_status=runtime_status,
            signal="long",
            confidence=42.0,
            last_price=42_000.0,
            reference_price=42_000.0,
            change_24h=0.0,
            note="",
            next_action="",
            last_evaluated_at="2026-04-22T08:00:00+08:00",
        )

    def _patch_clean_gates(self):
        """Neutralize every side-gate so each test exercises exactly one branch.

        Returns a list of ``patch`` context managers the caller enters via
        ``ExitStack``.  Without this helper every test would otherwise have to
        spell out the full set of mocks just to ensure "no other guard fires".
        """

        return [
            patch.object(
                control_main,
                "_strategy_live_stop_loss_cooldown_remaining_minutes",
                return_value=None,
            ),
            patch.object(
                control_main,
                "_has_active_strategy_live_stop_loss_alert",
                return_value=False,
            ),
            patch.object(
                control_main,
                "_strategy_exchange_rejection_guard_remaining_minutes",
                return_value=None,
            ),
            patch.object(
                control_main,
                "_strategy_auto_dispatch_gate_reason",
                return_value=None,
            ),
        ]

    def test_gate_blocks_paper_or_paused_strategy_and_clears_alerts(self) -> None:
        """A strategy on PAPER or with status ∈ {paper_only,paused,shadow}
        must block with ``auto.paper_or_paused_strategy`` and request both
        order cancellation and alert cleanup — the two cleanup side effects
        Round 60 pinned together for this terminal state.
        """

        from contextlib import ExitStack

        strategy = self._strategy(mode=AccountMode.PAPER)
        snapshot = self._snapshot()

        with ExitStack() as stack:
            for p in self._patch_clean_gates():
                stack.enter_context(p)
            gate = control_main._evaluate_strategy_auto_dispatch_gate(strategy, snapshot)

        self.assertEqual(gate.verdict, "block")
        self.assertEqual(gate.reason_code, "auto.paper_or_paused_strategy")
        self.assertTrue(gate.cancel_existing_orders)
        self.assertTrue(gate.clear_alerts)
        self.assertFalse(gate.record_issue)

