class ExchangeConstraintViolationTypedReturnRound78Tests(unittest.TestCase):
    """Round 78 — ``_validate_exchange_order_constraints`` now returns a typed
    :class:`ExchangeConstraintViolation` (``kind`` / ``message`` / ``limit_value``)
    instead of a free-form Chinese string.  Prior to R78 the downstream
    recommendation helper re-parsed the message with a brittle substring probe
    that silently missed the ``min_notional`` branch (copy says "最小下单金额"
    while the probe searched for "最小名义价值") — callers with a min-notional
    violation therefore got ``recommended_action=None`` despite being in a
    real exchange-constraint context.  The typed return + typed helper surface
    makes this class of breakage structurally impossible.

    Invariants pinned:

    1. Each of the four validator branches returns the expected
       :class:`ExchangeConstraintViolation.kind` with the historical
       Chinese ``message`` preserved verbatim.
    2. ``min_notional`` branch — previously silently dropped by the helper
       — now surfaces the canned recommendation via the typed helper.
    3. ``_build_exchange_constraint_recommended_action(None)`` short-circuits
       to ``None`` (non-violation inputs must never attach the canned copy).
    4. ``_build_exchange_constraint_recommended_action(violation)`` returns
       the canned recommendation for *every* ``kind`` — including the
       historically-broken ``min_notional`` case — without any substring
       gating on ``violation.message``.
    5. ``_build_execution_preview_recommended_action`` with
       ``block_code=RISK_REASON_EXCHANGE_CONSTRAINT`` and a ``min_notional``-
       flavoured detail now returns the canned recommendation (closes the
       R77 gap where typed-dispatch fell through to ``None`` because the
       helper's internal probe didn't match).
    """

    def _patched_constraints(self, *, min_qty: str, qty_step: str, tick_size: str, min_notional: str) -> Dict[str, Any]:
        return {
            "symbol": "BTCUSDT",
            "market": "spot",
            "min_order_qty": min_qty,
            "qty_step": qty_step,
            "tick_size": tick_size,
            "min_notional_value": min_notional,
        }

    def test_validator_min_order_qty_branch_returns_typed_violation(self) -> None:
        from models import ExchangeConstraintViolation  # noqa: PLC0415

        with patch.object(
            control_main.market_data,
            "get_instrument_constraints",
            return_value=self._patched_constraints(
                min_qty="0.01", qty_step="0.001", tick_size="0.1", min_notional="0"
            ),
        ):
            violation = control_main._validate_exchange_order_constraints(
                symbol="BTCUSDT", market="spot", quantity=0.001, price=50000.0
            )
        self.assertIsInstance(violation, ExchangeConstraintViolation)
        assert violation is not None
        self.assertEqual(violation.kind, "min_order_qty")
        self.assertIn("最小下单量", violation.message)
        self.assertAlmostEqual(violation.limit_value, 0.01)

    def test_validator_qty_step_branch_returns_typed_violation(self) -> None:
        from models import ExchangeConstraintViolation  # noqa: PLC0415

        with patch.object(
            control_main.market_data,
            "get_instrument_constraints",
            return_value=self._patched_constraints(
                min_qty="0", qty_step="0.01", tick_size="0.1", min_notional="0"
            ),
        ):
            violation = control_main._validate_exchange_order_constraints(
                symbol="BTCUSDT", market="spot", quantity=0.015, price=50000.0
            )
        self.assertIsInstance(violation, ExchangeConstraintViolation)
        assert violation is not None
        self.assertEqual(violation.kind, "qty_step")
        self.assertIn("数量步长", violation.message)
        self.assertAlmostEqual(violation.limit_value, 0.01)

    def test_validator_tick_size_branch_returns_typed_violation(self) -> None:
        from models import ExchangeConstraintViolation  # noqa: PLC0415

        with patch.object(
            control_main.market_data,
            "get_instrument_constraints",
            return_value=self._patched_constraints(
                min_qty="0", qty_step="0", tick_size="0.5", min_notional="0"
            ),
        ):
            violation = control_main._validate_exchange_order_constraints(
                symbol="BTCUSDT", market="spot", quantity=1.0, price=50000.25
            )
        self.assertIsInstance(violation, ExchangeConstraintViolation)
        assert violation is not None
        self.assertEqual(violation.kind, "tick_size")
        self.assertIn("价格步长", violation.message)
        self.assertAlmostEqual(violation.limit_value, 0.5)

    def test_validator_min_notional_branch_returns_typed_violation(self) -> None:
        from models import ExchangeConstraintViolation  # noqa: PLC0415

        with patch.object(
            control_main.market_data,
            "get_instrument_constraints",
            return_value=self._patched_constraints(
                min_qty="0", qty_step="0", tick_size="0", min_notional="100"
            ),
        ):
            violation = control_main._validate_exchange_order_constraints(
                symbol="BTCUSDT", market="spot", quantity=0.001, price=50.0
            )
        self.assertIsInstance(violation, ExchangeConstraintViolation)
        assert violation is not None
        self.assertEqual(violation.kind, "min_notional")
        # Historical copy preserved for wire compatibility.
        self.assertIn("名义价值", violation.message)
        self.assertIn("最小下单金额", violation.message)
        self.assertAlmostEqual(violation.limit_value, 100.0)

    def test_validator_returns_none_when_no_constraint_trips(self) -> None:
        with patch.object(
            control_main.market_data,
            "get_instrument_constraints",
            return_value=self._patched_constraints(
                min_qty="0.001", qty_step="0.001", tick_size="0.1", min_notional="5"
            ),
        ):
            violation = control_main._validate_exchange_order_constraints(
                symbol="BTCUSDT", market="spot", quantity=0.01, price=50000.0
            )
        self.assertIsNone(violation)

    def test_recommended_action_helper_short_circuits_on_none(self) -> None:
        self.assertIsNone(control_main._build_exchange_constraint_recommended_action(None))

    def test_recommended_action_helper_returns_canned_copy_for_every_kind(self) -> None:
        from models import ExchangeConstraintViolation  # noqa: PLC0415

        canned = (
            "请按 Bybit 的最小下单量、数量步长、价格步长和最小名义价值调整参数后再重试。"
        )
        for kind, message in (
            ("min_order_qty", "当前委托数量低于 Bybit 最小下单量 0.01，请调整数量后再提交。"),
            ("qty_step", "当前委托数量不符合 Bybit 数量步长 0.01，请按交易所步长调整后再提交。"),
            ("tick_size", "当前委托价格不符合 Bybit 价格步长 0.5，请按交易所报价精度调整后再提交。"),
            ("min_notional", "当前委托名义价值低于 Bybit 最小下单金额 100，请提高价格或数量后再提交。"),
        ):
            with self.subTest(kind=kind):
                violation = ExchangeConstraintViolation(
                    kind=kind,  # type: ignore[arg-type]
                    message=message,
                    limit_value=1.0,
                )
                self.assertEqual(
                    control_main._build_exchange_constraint_recommended_action(violation),
                    canned,
                )

    def test_typed_dispatch_recovers_min_notional_recommendation_previously_dropped(self) -> None:
        from models import RISK_REASON_EXCHANGE_CONSTRAINT  # noqa: PLC0415

        # Pre-R78 the R77 EXCHANGE_CONSTRAINT branch called the helper with
        # this detail string; the helper's probe searched for "最小名义价值"
        # which never matched, so the recommendation silently dropped to
        # ``None``.  The typed dispatch now returns the canned copy.
        result = control_main._build_execution_preview_recommended_action(
            "当前委托名义价值低于 Bybit 最小下单金额 10，请提高价格或数量后再提交。",
            block_code=RISK_REASON_EXCHANGE_CONSTRAINT,
        )
        self.assertEqual(
            result,
            "请按 Bybit 的最小下单量、数量步长、价格步长和最小名义价值调整参数后再重试。",
        )


class InsufficientBalanceMarketDiscriminatorRound79Tests(unittest.TestCase):
    """Round 79 — the ``RISK_REASON_INSUFFICIENT_BALANCE`` sub-dispatch in
    ``_build_execution_preview_recommended_action`` now keys spot vs perp copy
    off the typed ``market`` kwarg (already carried on every
    ``ExecutionPreview`` / ``StrategyRuntimeSnapshot``) rather than the
    ``"可用保证金不足"`` substring probe.  The substring path survives as a
    fallback only for callers that still invoke the helper without a typed
    ``market`` (e.g. audit-record paths that receive only the detail string).

    Invariants pinned:

    1. ``market="perp"`` → margin recommendation even when the detail does
       not contain ``"保证金"`` (typed discriminator wins).
    2. ``market="spot"`` → available-balance recommendation even when the
       detail *does* contain ``"保证金"`` (typed discriminator overrides the
       legacy substring probe).
    3. ``market=None`` → **deterministic spot-balance default** (R87 removed
       the legacy substring fallback; every in-tree caller now threads
       ``market`` or pre-computes the recommendation, so the substring
       probe was dead code).  Invariant is covered by the R87 observable-
       removal test class; the R79 suite no longer asserts the probe
       behaviour.
    4. ``_build_blocked_strategy_execution_preview`` threads
       ``market=snapshot.market`` end-to-end so the recommended_action
       emitted on the blocked preview uses the typed field.
    5. ``_build_auto_dispatch_recommended_action`` /
       ``_build_manual_execution_recommended_action`` accept ``market`` and
       forward it to the inner dispatch.
    """

    def setUp(self) -> None:
        self._account_patch = patch.object(
            control_main, "_resolve_private_account_type_label", return_value="UNIFIED"
        )
        self._account_patch.start()
        self.addCleanup(self._account_patch.stop)

    def test_typed_perp_market_returns_margin_copy_regardless_of_detail(self) -> None:
        from models import RISK_REASON_INSUFFICIENT_BALANCE  # noqa: PLC0415

        # Detail intentionally omits "保证金" so only the typed ``market``
        # can drive the margin branch.
        result = control_main._build_execution_preview_recommended_action(
            "当前 Bybit 可用余额不足，当前可用 0.00 USDT。",
            block_code=RISK_REASON_INSUFFICIENT_BALANCE,
            market="perp",
        )
        self.assertIsNotNone(result)
        assert result is not None
        self.assertIn("UNIFIED 账户可用保证金", result)
        self.assertNotIn("可用余额", result)

    def test_typed_spot_market_overrides_margin_substring(self) -> None:
        from models import RISK_REASON_INSUFFICIENT_BALANCE  # noqa: PLC0415

        # Detail contains "保证金不足" which the legacy substring probe would
        # have classified as perp; the typed ``market="spot"`` must override
        # and produce the available-balance copy.
        result = control_main._build_execution_preview_recommended_action(
            "当前可用保证金不足，当前可用 0.00 USDT。",
            block_code=RISK_REASON_INSUFFICIENT_BALANCE,
            market="spot",
        )
        self.assertIsNotNone(result)
        assert result is not None
        self.assertIn("UNIFIED 账户可用余额", result)
        self.assertNotIn("可用保证金", result)

    def test_blocked_strategy_execution_preview_threads_market_to_recommendation(self) -> None:
        from models import RISK_REASON_INSUFFICIENT_BALANCE  # noqa: PLC0415

        snapshot = StrategyRuntimeSnapshot(
            strategy_id="swing-eth-01",
            strategy_name="ETH 波段",
            symbol="ETHUSDT",
            market="perp",
            mode=AccountMode.LIVE,
            runtime_status="running",
            signal="long",
            confidence=50.0,
            last_price=3200.0,
            reference_price=3190.0,
            change_24h=0.3,
            note="",
            next_action="",
            last_evaluated_at="2026-04-22T00:00:00+08:00",
        )
        # Detail deliberately omits ``保证金`` so only ``snapshot.market="perp"``
        # can drive the margin branch — pins the end-to-end typed threading.
        detail = "当前 Bybit 可用余额不足，当前可用 0.00 USDT。"
        preview = control_main._build_blocked_strategy_execution_preview(
            snapshot,
            AccountMode.LIVE,
            detail,
            block_code=RISK_REASON_INSUFFICIENT_BALANCE,
        )
        self.assertEqual(preview.market, "perp")
        self.assertIsNotNone(preview.recommended_action)
        assert preview.recommended_action is not None
        self.assertIn("UNIFIED 账户可用保证金", preview.recommended_action)

    def test_auto_dispatch_recommended_action_forwards_market_kwarg(self) -> None:
        from models import RISK_REASON_INSUFFICIENT_BALANCE  # noqa: PLC0415

        _ = RISK_REASON_INSUFFICIENT_BALANCE  # import-for-side-effects only
        # Detail omits ``保证金``; ``market="perp"`` must flip the sub-dispatch.
        result = control_main._build_auto_dispatch_recommended_action(
            "当前 Bybit 可用余额不足，当前可用 0.00 USDT。",
            market="perp",
        )
        self.assertIn("UNIFIED 账户可用保证金", result)

    def test_manual_execution_recommended_action_forwards_market_kwarg(self) -> None:
        result = control_main._build_manual_execution_recommended_action(
            "当前可用保证金不足，当前可用 0.00 USDT。",
            market="spot",
        )
        self.assertIn("UNIFIED 账户可用余额", result)


class RuntimeUnavailableSubBlockCodeRound80Tests(unittest.TestCase):
    """Round 80 — the ``RISK_REASON_RUNTIME_UNAVAILABLE`` umbrella now splits
    into three typed sub-codes (``_PUBLIC_CHANNEL`` / ``_PRIVATE_CHANNEL`` /
    ``_WORKER_THREAD``) so ``_build_execution_preview_recommended_action``
    picks between channel-recovery / worker-thread recovery copy off a typed
    discriminator rather than ``"私有 WS"`` / ``"公共 WS"`` / ``"运行线程"``
    substring probes.

    Invariants pinned:

    1. ``StrategyExecutionChannelOutageError`` exposes ``sub_block_code``
       derived from ``channel=``: ``"public"`` →
       ``RISK_REASON_RUNTIME_UNAVAILABLE_PUBLIC_CHANNEL`` / ``"private"`` →
       ``RISK_REASON_RUNTIME_UNAVAILABLE_PRIVATE_CHANNEL`` / omitted → ``None``.
    2. ``_build_blocked_strategy_execution_preview`` accepts ``sub_block_code``
       and surfaces it on the ``ExecutionPreview`` instance.
    3. ``_build_execution_preview_recommended_action`` dispatches on the typed
       sub-code *before* the substring probe — typed wins over substring even
       when the two would disagree.
    4. Worker-thread sub-code returns the "恢复运行线程" copy without any
       ``"运行线程"`` detail substring (confirms typed-only path).
    5. When ``sub_block_code`` is omitted the legacy substring probe still
       classifies the detail so unconverted callers stay functional.
    6. ``_build_auto_dispatch_recommended_action`` /
       ``_build_manual_execution_recommended_action`` thread ``sub_block_code``
       through to the inner dispatch.
    """

    def test_channel_outage_public_exposes_typed_sub_block_code(self) -> None:
        from models import (  # noqa: PLC0415
            RISK_REASON_RUNTIME_UNAVAILABLE,
            RISK_REASON_RUNTIME_UNAVAILABLE_PUBLIC_CHANNEL,
        )

        exc = control_main.StrategyExecutionChannelOutageError(
            "公共 WS 行情已断线", channel="public"
        )
        self.assertEqual(exc.block_code, RISK_REASON_RUNTIME_UNAVAILABLE)
        self.assertEqual(exc.channel, "public")
        self.assertEqual(
            exc.sub_block_code,
            RISK_REASON_RUNTIME_UNAVAILABLE_PUBLIC_CHANNEL,
        )

    def test_channel_outage_private_exposes_typed_sub_block_code(self) -> None:
        from models import (  # noqa: PLC0415
            RISK_REASON_RUNTIME_UNAVAILABLE,
            RISK_REASON_RUNTIME_UNAVAILABLE_PRIVATE_CHANNEL,
        )

        exc = control_main.StrategyExecutionChannelOutageError(
            "私有 WS 下单链路未就绪", channel="private"
        )
        self.assertEqual(exc.block_code, RISK_REASON_RUNTIME_UNAVAILABLE)
        self.assertEqual(exc.channel, "private")
        self.assertEqual(
            exc.sub_block_code,
            RISK_REASON_RUNTIME_UNAVAILABLE_PRIVATE_CHANNEL,
        )

    def test_channel_outage_without_channel_leaves_sub_code_none(self) -> None:
        exc = control_main.StrategyExecutionChannelOutageError("通道掉线")
        self.assertIsNone(exc.channel)
        self.assertIsNone(exc.sub_block_code)

    def test_typed_public_channel_sub_code_overrides_private_substring(self) -> None:
        from models import (  # noqa: PLC0415
            RISK_REASON_RUNTIME_UNAVAILABLE,
            RISK_REASON_RUNTIME_UNAVAILABLE_PUBLIC_CHANNEL,
        )

        # Detail intentionally says "私有 WS" so the legacy substring probe
        # would pick private-channel copy; the typed sub-code must override.
        result = control_main._build_execution_preview_recommended_action(
            "私有 WS 下单链路未就绪，请先恢复连接。",
            block_code=RISK_REASON_RUNTIME_UNAVAILABLE,
            sub_block_code=RISK_REASON_RUNTIME_UNAVAILABLE_PUBLIC_CHANNEL,
        )
        self.assertIsNotNone(result)
        assert result is not None
        # The public-channel recommender copy is built from the detail string
        # by ``_build_public_execution_channel_recommended_action``; assert it
        # does not quote the private-channel canned copy.
        self.assertNotIn("私有 WS 下单链路", result)

    def test_typed_private_channel_sub_code_overrides_public_substring(self) -> None:
        from models import (  # noqa: PLC0415
            RISK_REASON_RUNTIME_UNAVAILABLE,
            RISK_REASON_RUNTIME_UNAVAILABLE_PRIVATE_CHANNEL,
        )

        result = control_main._build_execution_preview_recommended_action(
            "公共 WS 行情已断线，请先恢复连接。",
            block_code=RISK_REASON_RUNTIME_UNAVAILABLE,
            sub_block_code=RISK_REASON_RUNTIME_UNAVAILABLE_PRIVATE_CHANNEL,
        )
        self.assertIsNotNone(result)
        assert result is not None
        self.assertNotIn("公共 WS", result)

    def test_typed_worker_thread_sub_code_returns_canned_copy_without_detail_substring(self) -> None:
        from models import (  # noqa: PLC0415
            RISK_REASON_RUNTIME_UNAVAILABLE,
            RISK_REASON_RUNTIME_UNAVAILABLE_WORKER_THREAD,
        )

        # Detail deliberately omits the ``"运行线程"`` token so only the
        # typed sub-code can drive the canned worker-thread copy.
        result = control_main._build_execution_preview_recommended_action(
            "后台调度未就绪，请稍后重试。",
            block_code=RISK_REASON_RUNTIME_UNAVAILABLE,
            sub_block_code=RISK_REASON_RUNTIME_UNAVAILABLE_WORKER_THREAD,
        )
        self.assertEqual(
            result,
            "打开设置页点击“恢复运行线程”，并确认最近审计日志与最新信号。",
        )

    def test_sub_code_omitted_returns_none_after_substring_removal(self) -> None:
        """Round 88 — the R80 substring fallback inside the RUNTIME_UNAVAILABLE
        umbrella branch was removed.  When the caller passes only the umbrella
        ``block_code`` without a typed ``sub_block_code``, the helper now
        returns ``None`` so the downstream ``or fallback`` short-circuit
        decides the recovery copy.  The three legacy substring probes
        (``"私有 WS"`` / ``"公共 WS"`` / ``"运行线程"``) are no longer consulted.
        """

        from models import RISK_REASON_RUNTIME_UNAVAILABLE  # noqa: PLC0415

        for detail in (
            "私有 WS 下单链路未就绪，请先恢复连接。",
            "公共 WS 行情已断线，请先恢复连接。",
            "当前策略运行线程已停滞，请先在设置页恢复运行线程。",
        ):
            result = control_main._build_execution_preview_recommended_action(
                detail,
                block_code=RISK_REASON_RUNTIME_UNAVAILABLE,
            )
            self.assertIsNone(
                result,
                msg=f"unexpected recommendation for detail {detail!r} after R88 substring removal",
            )

    def test_blocked_strategy_execution_preview_surfaces_sub_block_code(self) -> None:
        from models import (  # noqa: PLC0415
            RISK_REASON_RUNTIME_UNAVAILABLE,
            RISK_REASON_RUNTIME_UNAVAILABLE_WORKER_THREAD,
        )

        snapshot = StrategyRuntimeSnapshot(
            strategy_id="swing-eth-01",
            strategy_name="ETH 波段",
            symbol="ETHUSDT",
            market="perp",
            mode=AccountMode.LIVE,
            runtime_status="running",
            signal="long",
            confidence=50.0,
            last_price=3200.0,
            reference_price=3190.0,
            change_24h=0.3,
            note="",
            next_action="",
            last_evaluated_at="2026-04-22T00:00:00+08:00",
        )
        # Detail deliberately omits the ``"运行线程"`` token; only the typed
        # sub-code can drive the canned copy — pins end-to-end threading.
        preview = control_main._build_blocked_strategy_execution_preview(
            snapshot,
            AccountMode.LIVE,
            "后台调度未就绪，请稍后重试。",
            block_code=RISK_REASON_RUNTIME_UNAVAILABLE,
            sub_block_code=RISK_REASON_RUNTIME_UNAVAILABLE_WORKER_THREAD,
        )
        self.assertEqual(preview.block_code, RISK_REASON_RUNTIME_UNAVAILABLE)
        self.assertEqual(
            preview.sub_block_code,
            RISK_REASON_RUNTIME_UNAVAILABLE_WORKER_THREAD,
        )
        self.assertEqual(
            preview.recommended_action,
            "打开设置页点击“恢复运行线程”，并确认最近审计日志与最新信号。",
        )

    def test_auto_dispatch_recommended_action_forwards_sub_block_code(self) -> None:
        from models import RISK_REASON_RUNTIME_UNAVAILABLE_WORKER_THREAD  # noqa: PLC0415

        # Detail without any legacy substring — only the typed sub-code can
        # drive the worker-thread copy.
        result = control_main._build_auto_dispatch_recommended_action(
            "后台调度未就绪，请稍后重试。",
            sub_block_code=RISK_REASON_RUNTIME_UNAVAILABLE_WORKER_THREAD,
        )
        self.assertEqual(
            result,
            "打开设置页点击“恢复运行线程”，并确认最近审计日志与最新信号。",
        )

    def test_manual_execution_recommended_action_forwards_sub_block_code(self) -> None:
        from models import RISK_REASON_RUNTIME_UNAVAILABLE_PRIVATE_CHANNEL  # noqa: PLC0415

        # Detail says "公共 WS" (legacy probe would pick public copy); the
        # typed sub-code must override to the private-channel path.
        result = control_main._build_manual_execution_recommended_action(
            "公共 WS 行情已断线，请先恢复连接。",
            sub_block_code=RISK_REASON_RUNTIME_UNAVAILABLE_PRIVATE_CHANNEL,
        )
        self.assertNotIn("公共 WS", result)


class StopLossGuardTypedBlockCodeRound82Tests(unittest.TestCase):
    """Round 82 — lift the ``"止损保护"`` substring probe in
    ``_build_execution_preview_recommended_action`` to a typed
    ``RISK_REASON_STOP_LOSS_GUARD`` code set at the preview-builder source.

    Invariants pinned:

    1. ``derive_block_reason_code`` classifies the canonical live-stop-loss
       copy onto ``RISK_REASON_STOP_LOSS_GUARD`` (legacy audit strings stay
       classified even when they arrive without a typed ``block_code``).
    2. ``derive_block_reason_code`` is conservative: unrelated details still
       fall back to ``RISK_REASON_PREVIEW_BLOCKED``.
    3. ``_build_execution_preview_recommended_action`` dispatches on the
       typed code (``block_code=RISK_REASON_STOP_LOSS_GUARD``) even when the
       detail omits the ``"止损保护"`` token — proving typed-first dispatch.
    4. The legacy substring still classifies via ``derive_block_reason_code``
       so unconverted callers (audit record re-rendering) keep working.
    5. ``ExecutionPreview.block_code`` round-trips via ``evaluate_risk_decision``
       onto ``RiskDecision.reason_code``.
    """

    def test_derive_block_reason_code_classifies_stop_loss_guard_detail(self) -> None:
        from models import RISK_REASON_STOP_LOSS_GUARD  # noqa: PLC0415
        from risk_decision import derive_block_reason_code  # noqa: PLC0415

        detail = "当前已触发真实模式止损保护，请先人工复核真实仓位后再决定是否恢复策略执行。"
        self.assertEqual(derive_block_reason_code(detail), RISK_REASON_STOP_LOSS_GUARD)

    def test_derive_block_reason_code_ignores_unrelated_detail(self) -> None:
        from models import RISK_REASON_PREVIEW_BLOCKED  # noqa: PLC0415
        from risk_decision import derive_block_reason_code  # noqa: PLC0415

        # An unrelated free-form detail must not spuriously classify as
