class ExchangeOrderStatusEventClassifierRound101Tests(unittest.TestCase):
    """Round 101 — the ``(status → event_type, severity)`` mapping used to
    project Bybit exchange-order history onto the ``exchange_order.*`` audit
    family was duplicated across ``_sync_strategy_exchange_order_history_events``
    and ``_resolve_strategy_recent_execution_event`` with byte-identical
    ``if "fill" … elif "cancel" … elif "reject" …`` ladders.  R101 extracts the
    classifier onto the module helper ``_classify_exchange_order_status_event``
    so both callsites share one definition.  These tests pin the classifier's
    observable contract:

    1. Canonical Bybit statuses (``"Filled"`` / ``"Cancelled"`` / ``"Rejected"``)
       each return the typed ``(event_type, EventSeverity)`` tuple.
    2. Mixed-case and compound statuses (``"PartiallyFilled"`` /
       ``"PartiallyFilledCanceled"``) lowercase-then-substring match — the
       ``"fill"`` probe fires first on ``"PartiallyFilledCanceled"`` because
       the legacy ladder ordered ``fill`` ahead of ``cancel``.
    3. Unknown statuses return ``None`` so callers branch on the ``Optional``
       result rather than substring-probing again at the callsite.
    """

    def test_filled_status_returns_typed_tuple(self) -> None:
        self.assertEqual(
            control_main._classify_exchange_order_status_event("Filled"),
            ("exchange_order.filled", control_main.EventSeverity.INFO),
        )

    def test_cancelled_status_returns_typed_tuple(self) -> None:
        self.assertEqual(
            control_main._classify_exchange_order_status_event("Cancelled"),
            ("exchange_order.cancelled", control_main.EventSeverity.WARNING),
        )

    def test_rejected_status_returns_typed_tuple(self) -> None:
        self.assertEqual(
            control_main._classify_exchange_order_status_event("Rejected"),
            ("exchange_order.rejected", control_main.EventSeverity.ERROR),
        )

    def test_partially_filled_status_matches_fill(self) -> None:
        self.assertEqual(
            control_main._classify_exchange_order_status_event("PartiallyFilled"),
            ("exchange_order.filled", control_main.EventSeverity.INFO),
        )

    def test_partially_filled_canceled_prefers_fill_per_legacy_ordering(self) -> None:
        # ``"PartiallyFilledCanceled"`` contains both ``"fill"`` and ``"cancel"``
        # substrings; the legacy ladder placed ``"fill"`` first so the helper
        # returns filled to preserve audit-feed continuity.
        self.assertEqual(
            control_main._classify_exchange_order_status_event("PartiallyFilledCanceled"),
            ("exchange_order.filled", control_main.EventSeverity.INFO),
        )

    def test_unknown_status_returns_none(self) -> None:
        # Legacy callsite #1 (``_sync_strategy_exchange_order_history_events``)
        # short-circuits on ``None``; callsite #2
        # (``_resolve_strategy_recent_execution_event``) falls back to
        # ``exchange_order.updated`` at the callsite.
        self.assertIsNone(control_main._classify_exchange_order_status_event("New"))
        self.assertIsNone(control_main._classify_exchange_order_status_event("Untriggered"))
        self.assertIsNone(control_main._classify_exchange_order_status_event(""))

    def test_status_is_lowercased_before_substring_probe(self) -> None:
        # Probe the helper with an uppercase variant that could not possibly
        # match a case-sensitive substring on ``"fill"`` / ``"cancel"`` /
        # ``"reject"``, proving the ``.lower()`` call fires at source.
        self.assertEqual(
            control_main._classify_exchange_order_status_event("FILLED"),
            ("exchange_order.filled", control_main.EventSeverity.INFO),
        )
        self.assertEqual(
            control_main._classify_exchange_order_status_event("CANCELLED"),
            ("exchange_order.cancelled", control_main.EventSeverity.WARNING),
        )
        self.assertEqual(
            control_main._classify_exchange_order_status_event("REJECTED"),
            ("exchange_order.rejected", control_main.EventSeverity.ERROR),
        )


class NonRunningStrategyStatusesConstantRound102Tests(unittest.TestCase):
    """Round 102 — the inline set literal ``{"paper_only", "paused", "shadow"}``
    was duplicated across three callsites
    (``_strategy_exchange_rejection_guard_remaining_minutes`` /
    ``_sync_strategy_live_stop_loss_alerts`` /
    ``_evaluate_strategy_auto_dispatch_gate``) that all gate the autonomous
    live-dispatch pipeline on "is this strategy in a non-running state?".
    R102 extracts the set onto the module constant
    :data:`_NON_RUNNING_STRATEGY_STATUSES` so any future status extension
    surfaces as a single audit point.  These tests pin:

    1. The constant is a ``frozenset`` (immutable — protects against accidental
       mutation by consumers).
    2. The constant's members are exactly ``{"paper_only", "paused", "shadow"}``.
    3. The constant equals the complement of ``"running"`` within the
       :class:`StrategySummary` ``status`` ``Literal`` — i.e. ``"running"``
       is the only status NOT in the gated set — so the enum-level invariant
       ("the set represents not-running") is reinforced.
    4. The auto-dispatch gate, rejection-guard remaining, and stop-loss-alert
       sync all consult the constant rather than an inline set literal.
    """

    def test_constant_is_frozenset_not_mutable_set(self) -> None:
        self.assertIsInstance(control_main._NON_RUNNING_STRATEGY_STATUSES, frozenset)

    def test_constant_members_match_non_running_statuses(self) -> None:
        self.assertEqual(
            set(control_main._NON_RUNNING_STRATEGY_STATUSES),
            {"paper_only", "paused", "shadow"},
        )

    def test_constant_equals_literal_complement_of_running(self) -> None:
        # The ``StrategySummary.status`` field is typed
        # ``Literal["running", "paused", "paper_only", "shadow"]``; the
        # constant should be exactly that enum minus ``"running"`` so a future
        # status addition is forced to explicitly opt in or out of the gate.
        all_statuses: set = {"running", "paused", "paper_only", "shadow"}
        self.assertEqual(
            set(control_main._NON_RUNNING_STRATEGY_STATUSES),
            all_statuses - {"running"},
        )

    def test_auto_dispatch_gate_blocks_each_non_running_status(self) -> None:
        # All three statuses in the constant should trigger the
        # ``auto.paper_or_paused_strategy`` gate regardless of mode.
        strategy_tmpl = SimpleNamespace(
            id="gate-status-probe",
            mode=control_main.AccountMode.LIVE,
            status="running",
        )
        snapshot_tmpl = SimpleNamespace(strategy_id="gate-status-probe", runtime_status="running")
        for status in control_main._NON_RUNNING_STRATEGY_STATUSES:
            with self.subTest(status=status):
                strategy = SimpleNamespace(
                    id="gate-status-probe",
                    mode=control_main.AccountMode.LIVE,
                    status=status,
                )
                gate = control_main._evaluate_strategy_auto_dispatch_gate(strategy, snapshot_tmpl)
                self.assertEqual(gate.verdict, "block")
                self.assertEqual(gate.reason_code, "auto.paper_or_paused_strategy")

    def test_auto_dispatch_gate_allows_running_status_past_mode_gate(self) -> None:
        # ``"running"`` is the one status NOT in the gated set so the gate
        # passes the mode/status check (the subsequent branches will make
        # their own decisions — this test only verifies the early-return
        # branch does not fire for ``"running"``).
        strategy = SimpleNamespace(
            id="gate-status-probe",
            mode=control_main.AccountMode.LIVE,
            status="running",
        )
        self.assertNotIn(strategy.status, control_main._NON_RUNNING_STRATEGY_STATUSES)


class NonPaperAccountModesConstantRound103Tests(unittest.TestCase):
    """Round 103 — the inline set literal ``{AccountMode.DEMO, AccountMode.LIVE}``
    (and its reversed variant ``{AccountMode.LIVE, AccountMode.DEMO}``) was
    duplicated at 11 callsites across ``main.py`` and
    ``alert_and_guard_sync.py``, each gating real-market-connection branches
    against paper-mode fallback.  R103 extracts the set onto the public
    constant :data:`models.NON_PAPER_ACCOUNT_MODES` so any future account mode
    addition surfaces as a single audit point.  These tests pin:

    1. The constant is a ``frozenset`` (immutable).
    2. The constant's members are exactly ``{AccountMode.DEMO, AccountMode.LIVE}``.
    3. The constant equals the complement of :attr:`AccountMode.PAPER` within
       the enum, so ``NON_PAPER_ACCOUNT_MODES | {PAPER}`` covers every
       ``AccountMode`` member.
    4. The constant is re-exported through ``main.py``'s models import so
       legacy call-sites that read it off the module keep working.
    """

    def test_constant_is_frozenset_not_mutable_set(self) -> None:
        from models import NON_PAPER_ACCOUNT_MODES

        self.assertIsInstance(NON_PAPER_ACCOUNT_MODES, frozenset)

    def test_constant_members_match_non_paper_account_modes(self) -> None:
        from models import AccountMode, NON_PAPER_ACCOUNT_MODES

        self.assertEqual(
            set(NON_PAPER_ACCOUNT_MODES),
            {AccountMode.DEMO, AccountMode.LIVE},
        )

    def test_constant_equals_complement_of_paper_within_enum(self) -> None:
        from models import AccountMode, NON_PAPER_ACCOUNT_MODES

        # ``AccountMode`` is a ``str Enum`` with three members — ``PAPER`` /
        # ``DEMO`` / ``LIVE``.  The constant should be exactly ``all - {PAPER}``.
        all_modes: set = set(AccountMode)
        self.assertEqual(set(NON_PAPER_ACCOUNT_MODES), all_modes - {AccountMode.PAPER})

    def test_main_module_reexports_constant(self) -> None:
        # ``main.py`` imports ``NON_PAPER_ACCOUNT_MODES`` off ``models`` so the
        # 8 callsites inside ``main.py`` reference the same object.
        from models import NON_PAPER_ACCOUNT_MODES

        self.assertIs(control_main.NON_PAPER_ACCOUNT_MODES, NON_PAPER_ACCOUNT_MODES)

    def test_paper_mode_excluded_from_constant(self) -> None:
        from models import AccountMode, NON_PAPER_ACCOUNT_MODES

        self.assertNotIn(AccountMode.PAPER, NON_PAPER_ACCOUNT_MODES)
        self.assertIn(AccountMode.DEMO, NON_PAPER_ACCOUNT_MODES)
        self.assertIn(AccountMode.LIVE, NON_PAPER_ACCOUNT_MODES)


class RiskEngineRound118Tests(unittest.TestCase):
    """Round 118 — :class:`risk_engine.RiskEngine` parity regression suite.

    Wave-2-A introduced the unified :class:`RiskEngine` coordinator that wraps
    the typed risk-decision graph (``evaluate_risk_decision`` /
    ``_evaluate_strategy_auto_dispatch_gate`` / ``_classify_auto_dispatch_outcome``)
    behind a single typed API.  The engine is **stateless** — every method
    delegates verbatim to the underlying helper kept inside ``main.py`` /
    ``risk_decision.py``.

    These tests pin the parity contract:

    1. ``RiskEngine.evaluate_preview`` returns a decision byte-identical to
       calling ``risk_decision.evaluate_risk_decision`` directly (allow + block
       paths, with and without an explicit ``recommended_action``).
    2. ``RiskEngine.evaluate_auto_dispatch_gate`` returns the same
       :class:`AutoDispatchGate` as the underlying R60 helper across the
       documented verdict spectrum (paper-or-paused / live-stop-loss /
       runtime-not-running / ready).
    3. ``RiskEngine.classify_outcome`` returns the same
       :class:`AutoDispatchOutcome` as the underlying R61 helper across the
       four typed verdicts (dispatched / noop / blocked / failed).
    4. ``main.py`` exposes a module-level ``risk_engine`` singleton instance
       so the call-sites refactored in R118 pick up the same coordinator.
    """

    @staticmethod
    def _build_allowed_preview():
        """Return a minimal allowed :class:`ExecutionPreview`."""

        from models import ExecutionPreview as _Preview  # noqa: PLC0415

        return _Preview(
            symbol="BTCUSDT",
            market="perp",
            mode=AccountMode.PAPER,
            side=Direction.BUY,
            origin="manual",
            quantity=0.5,
            price=42_000.0,
            notional="21000.00",
            action="开多",
            allowed=True,
            blocked_reason=None,
            recommended_action=None,
            warnings=[],
            current_position_size="0",
            current_avg_price="--",
            projected_position_size="0.5",
            projected_avg_price="42000.00",
            available_balance_before="50000.00",
            available_balance_after="29000.00",
            estimated_realized_pnl="--",
            generated_at="2026-04-26T08:00:00+08:00",
        )

    @staticmethod
    def _build_blocked_preview(blocked_reason: str, *, recommended_action: Optional[str] = None):
        """Return a minimal blocked :class:`ExecutionPreview`."""

        from models import ExecutionPreview as _Preview  # noqa: PLC0415

        return _Preview(
            symbol="BTCUSDT",
            market="perp",
            mode=AccountMode.PAPER,
            side=Direction.BUY,
            origin="manual",
            quantity=0.5,
            price=42_000.0,
            notional="21000.00",
            action="开多",
            allowed=False,
            blocked_reason=blocked_reason,
            recommended_action=recommended_action,
            warnings=[blocked_reason],
            current_position_size="0",
            current_avg_price="--",
            projected_position_size="--",
            projected_avg_price="--",
            available_balance_before="50000.00",
            available_balance_after="--",
            estimated_realized_pnl="--",
            generated_at="2026-04-26T08:00:00+08:00",
        )

    @staticmethod
    def _build_strategy(*, mode: AccountMode = AccountMode.LIVE, status: str = "running"):
        """Return a minimal :class:`StrategySummary` for gate tests."""

        from models import StrategySummary as _Strategy  # noqa: PLC0415

        return _Strategy(
            id="risk-engine-r118-01",
            name="RiskEngineHarness",
            category="template",
            status=status,
            symbols=["BTCUSDT"],
            mode=mode,
            version="v1",
            pnl_7d="+0.0%",
            max_drawdown="-0.0%",
            risk_budget="10%",
            description="R118 risk-engine harness",
            parameters=[StrategyParameter(key="noop", label="noop", value=0.0)],
        )

    @staticmethod
    def _build_snapshot(*, runtime_status: str = "running"):
        """Return a minimal :class:`StrategyRuntimeSnapshot` for gate tests."""

        return StrategyRuntimeSnapshot(
            strategy_id="risk-engine-r118-01",
            strategy_name="RiskEngineHarness",
            symbol="BTCUSDT",
            market="perp",
            mode=AccountMode.LIVE,
            runtime_status=runtime_status,
            signal="long",
            confidence=42.0,
            last_price=42_000.0,
            reference_price=42_000.0,
            change_24h=0.0,
            note="",
            next_action="",
            last_evaluated_at="2026-04-26T08:00:00+08:00",
        )

    @staticmethod
    def _patch_clean_gates():
        """Neutralise every side-gate so ``evaluate_auto_dispatch_gate`` runs
        the requested branch without falling through to scheduler / channel
        side-effects.  Mirrors ``AutoDispatchGateRound60UnitTests._patch_clean_gates``
        so the parity contract uses the same neutral fixture."""

        return [
            patch.object(
                control_main,
                "_strategy_live_stop_loss_cooldown_remaining_minutes",
                return_value=None,
            ),
            patch.object(
                control_main,
                "_has_active_strategy_live_stop_loss_alert",
                return_value=False,
            ),
            patch.object(
                control_main,
                "_strategy_exchange_rejection_guard_remaining_minutes",
                return_value=None,
            ),
            patch.object(
                control_main,
                "_strategy_auto_dispatch_gate_reason",
                return_value=None,
            ),
        ]

    # ------------------------------------------------------------------
    # Singleton + module surface tests
    # ------------------------------------------------------------------

    def test_main_module_exposes_risk_engine_singleton_instance(self) -> None:
        """``main.py`` must expose a module-level :data:`risk_engine` singleton
        so every refactored call-site reads the same coordinator instance."""

        from risk_engine import RiskEngine  # noqa: PLC0415

        self.assertTrue(hasattr(control_main, "risk_engine"))
        self.assertIsInstance(control_main.risk_engine, RiskEngine)

    def test_risk_engine_is_stateless_no_dict_or_instance_attributes(self) -> None:
        """Wave-2-A's :class:`RiskEngine` is a stateless coordinator — every
        method delegates to the underlying helper, so the instance must not
        accumulate per-call state.  ``__slots__ = ()`` guarantees attribute
        assignment raises :class:`AttributeError`, pinning the no-state
        contract at the type level."""

        with self.assertRaises(AttributeError):
            control_main.risk_engine.some_arbitrary_attr = 42  # type: ignore[attr-defined]

    # ------------------------------------------------------------------
    # evaluate_preview parity tests
    # ------------------------------------------------------------------

    def test_evaluate_preview_allow_path_matches_underlying_helper(self) -> None:
        """``RiskEngine.evaluate_preview`` on an ``allowed=True`` preview must
        return the same ``verdict`` / ``reason_code`` / ``preview`` reference
        as ``risk_decision.evaluate_risk_decision`` — the engine is a thin
        delegator and must not transform the verdict."""

        import risk_decision  # noqa: PLC0415
        from models import RISK_REASON_APPROVED  # noqa: PLC0415

        preview = self._build_allowed_preview()
        engine_decision = control_main.risk_engine.evaluate_preview(preview)
        helper_decision = risk_decision.evaluate_risk_decision(preview)

        self.assertEqual(engine_decision.verdict, "allow")
        self.assertEqual(engine_decision.reason_code, RISK_REASON_APPROVED)
        self.assertIs(engine_decision.preview, preview)
        # Parity: the engine and the underlying helper must agree.
        self.assertEqual(engine_decision.verdict, helper_decision.verdict)
        self.assertEqual(engine_decision.reason_code, helper_decision.reason_code)
        self.assertEqual(engine_decision.reason_detail, helper_decision.reason_detail)

    def test_evaluate_preview_block_path_carries_typed_reason_code(self) -> None:
        """A blocked preview with insufficient-balance copy must surface the
        ``risk.insufficient_balance`` typed reason code through the engine —
        the substring-probe / typed ``block_code`` dispatch lives inside
        ``derive_block_reason_code`` / ``RiskDecision.reason_code`` and the
        engine must not mask either branch."""

        import risk_decision  # noqa: PLC0415
        from models import RISK_REASON_INSUFFICIENT_BALANCE  # noqa: PLC0415

        preview = self._build_blocked_preview(
            "当前 Paper 可用余额不足，缺口 2000 USDT。",
            recommended_action="请先补充 Paper 可用余额。",
        )
        engine_decision = control_main.risk_engine.evaluate_preview(preview)
        helper_decision = risk_decision.evaluate_risk_decision(preview)

        self.assertEqual(engine_decision.verdict, "block")
        self.assertEqual(engine_decision.reason_code, RISK_REASON_INSUFFICIENT_BALANCE)
        self.assertIn("可用余额不足", engine_decision.reason_detail)
        # Parity with the underlying helper.
        self.assertEqual(engine_decision.verdict, helper_decision.verdict)
        self.assertEqual(engine_decision.reason_code, helper_decision.reason_code)
        self.assertEqual(engine_decision.reason_detail, helper_decision.reason_detail)
        assert engine_decision.recommended_action is not None
        self.assertEqual(
            engine_decision.recommended_action.recommendation,
            "请先补充 Paper 可用余额。",
        )

    def test_evaluate_preview_forwards_explicit_recommended_action_kwarg(self) -> None:
        """When the caller passes an explicit
        :class:`RiskDecisionRecommendation`, the engine must forward it
        verbatim instead of synthesising one from the preview's free-form
        ``recommended_action`` string."""

        from models import RiskDecisionRecommendation  # noqa: PLC0415

        preview = self._build_blocked_preview(
            "当前敞口已接近上限，请按 30% 规模继续。",
            recommended_action="请先复核敞口预算。",
        )
        explicit = RiskDecisionRecommendation(size_multiplier=0.3)

        decision = control_main.risk_engine.evaluate_preview(
            preview, recommended_action=explicit
        )

        self.assertEqual(decision.verdict, "block")
        # The explicit recommendation must override the preview's free-form one.
        assert decision.recommended_action is not None
        self.assertEqual(decision.recommended_action.size_multiplier, 0.3)
        self.assertIsNone(decision.recommended_action.recommendation)

    # ------------------------------------------------------------------
    # evaluate_auto_dispatch_gate parity tests
    # ------------------------------------------------------------------

    def test_evaluate_auto_dispatch_gate_paper_status_matches_helper(self) -> None:
        """A strategy on PAPER mode must produce the same
        ``auto.paper_or_paused_strategy`` gate verdict whether the caller
        invokes ``main._evaluate_strategy_auto_dispatch_gate`` or the engine
        wrapper."""

        from contextlib import ExitStack  # noqa: PLC0415

        strategy = self._build_strategy(mode=AccountMode.PAPER)
        snapshot = self._build_snapshot()

        with ExitStack() as stack:
            for p in self._patch_clean_gates():
                stack.enter_context(p)
            engine_gate = control_main.risk_engine.evaluate_auto_dispatch_gate(
                strategy, snapshot
            )
            helper_gate = control_main._evaluate_strategy_auto_dispatch_gate(
                strategy, snapshot
            )

        self.assertEqual(engine_gate.verdict, "block")
        self.assertEqual(engine_gate.reason_code, "auto.paper_or_paused_strategy")
        # Parity: every documented public field on the gate matches.
        self.assertEqual(engine_gate.verdict, helper_gate.verdict)
        self.assertEqual(engine_gate.reason_code, helper_gate.reason_code)
        self.assertEqual(
            engine_gate.cancel_existing_orders, helper_gate.cancel_existing_orders
        )
        self.assertEqual(engine_gate.clear_alerts, helper_gate.clear_alerts)
        self.assertEqual(engine_gate.record_issue, helper_gate.record_issue)

    def test_evaluate_auto_dispatch_gate_runtime_not_running_matches_helper(self) -> None:
        """When the snapshot's ``runtime_status`` is anything other than
        ``"running"`` and every other guard passes, the engine + helper must
        agree on ``auto.runtime_not_running`` with both cleanup flags
        (``cancel_existing_orders`` + ``clear_alerts``) on.

        The strategy is kept in ``"running"`` (so the leading
        ``_NON_RUNNING_STRATEGY_STATUSES`` gate does not fire) while the
        snapshot's ``runtime_status`` is ``"paused"`` to drive the late-stage
        ``auto.runtime_not_running`` branch."""

        from contextlib import ExitStack  # noqa: PLC0415

        strategy = self._build_strategy()
        snapshot = self._build_snapshot(runtime_status="paused")

        with ExitStack() as stack:
            for p in self._patch_clean_gates():
                stack.enter_context(p)
            engine_gate = control_main.risk_engine.evaluate_auto_dispatch_gate(
                strategy, snapshot
            )
            helper_gate = control_main._evaluate_strategy_auto_dispatch_gate(
                strategy, snapshot
            )

        self.assertEqual(engine_gate.verdict, "block")
        self.assertEqual(engine_gate.reason_code, "auto.runtime_not_running")
        self.assertTrue(engine_gate.cancel_existing_orders)
        self.assertTrue(engine_gate.clear_alerts)
        # Parity check.
        self.assertEqual(engine_gate.verdict, helper_gate.verdict)
        self.assertEqual(engine_gate.reason_code, helper_gate.reason_code)

    def test_evaluate_auto_dispatch_gate_ready_path_matches_helper(self) -> None:
        """With every guard neutralised and the snapshot in ``"running"``, the
        engine and helper must both surface ``auto.ready`` (verdict allow,
        zero side effects)."""

        from contextlib import ExitStack  # noqa: PLC0415

        strategy = self._build_strategy()
        snapshot = self._build_snapshot()

        with ExitStack() as stack:
            for p in self._patch_clean_gates():
                stack.enter_context(p)
            engine_gate = control_main.risk_engine.evaluate_auto_dispatch_gate(
                strategy, snapshot
            )
            helper_gate = control_main._evaluate_strategy_auto_dispatch_gate(
                strategy, snapshot
            )

        self.assertEqual(engine_gate.verdict, "allow")
        self.assertEqual(engine_gate.reason_code, "auto.ready")
        self.assertFalse(engine_gate.cancel_existing_orders)
        self.assertFalse(engine_gate.clear_alerts)
        self.assertFalse(engine_gate.record_issue)
        # Parity.
        self.assertEqual(engine_gate.verdict, helper_gate.verdict)
        self.assertEqual(engine_gate.reason_code, helper_gate.reason_code)

    # ------------------------------------------------------------------
    # classify_outcome parity tests
    # ------------------------------------------------------------------

    def test_classify_outcome_dispatched_when_no_exception(self) -> None:
        """``RiskEngine.classify_outcome(None)`` must surface the same
        ``dispatched`` / ``auto.dispatch.success`` verdict + side-effect flags
        as the underlying R61 helper."""

        engine_outcome = control_main.risk_engine.classify_outcome(None)
        helper_outcome = control_main._classify_auto_dispatch_outcome(None)

        self.assertEqual(engine_outcome.verdict, "dispatched")
        self.assertEqual(engine_outcome.reason_code, "auto.dispatch.success")
        self.assertTrue(engine_outcome.clear_alerts)
        self.assertFalse(engine_outcome.emit_noop_event)
        self.assertFalse(engine_outcome.record_issue)
        # Parity.
        self.assertEqual(engine_outcome.verdict, helper_outcome.verdict)
        self.assertEqual(engine_outcome.reason_code, helper_outcome.reason_code)
        self.assertEqual(engine_outcome.clear_alerts, helper_outcome.clear_alerts)
        self.assertEqual(
            engine_outcome.emit_noop_event, helper_outcome.emit_noop_event
        )
        self.assertEqual(engine_outcome.record_issue, helper_outcome.record_issue)

    def test_classify_outcome_noop_from_typed_subclass_matches_helper(self) -> None:
        """A :class:`StrategyExecutionNoopError` must surface as ``noop`` /
        ``auto.dispatch.noop`` with ``emit_noop_event=True`` through the
        engine — pinning the R81 typed-raise contract through the engine
        layer."""

        exc = control_main.StrategyExecutionNoopError(
            "当前挂单已与目标一致，无需再次提交委托。"
        )

        engine_outcome = control_main.risk_engine.classify_outcome(exc)
        helper_outcome = control_main._classify_auto_dispatch_outcome(exc)

        self.assertEqual(engine_outcome.verdict, "noop")
        self.assertEqual(engine_outcome.reason_code, "auto.dispatch.noop")
        self.assertTrue(engine_outcome.emit_noop_event)
        # Parity with the underlying helper across every flag.
        self.assertEqual(engine_outcome.verdict, helper_outcome.verdict)
        self.assertEqual(engine_outcome.reason_code, helper_outcome.reason_code)
        self.assertEqual(engine_outcome.reason_detail, helper_outcome.reason_detail)
        self.assertEqual(engine_outcome.clear_alerts, helper_outcome.clear_alerts)
        self.assertEqual(
            engine_outcome.emit_noop_event, helper_outcome.emit_noop_event
        )
        self.assertEqual(engine_outcome.record_issue, helper_outcome.record_issue)

    def test_classify_outcome_blocked_propagates_recommended_action(self) -> None:
        """``StrategyExecutionBlockedError`` carries an
        ``recommended_action``; the engine must propagate it onto
        ``AutoDispatchOutcome.recommended_action`` so the operator console
        can render the next-step button."""

        exc = control_main.StrategyExecutionBlockedError(
            "当前 Live 余额不足，暂缓自动执行。",
            recommended_action="请先补充 Live 可用余额。",
        )

        engine_outcome = control_main.risk_engine.classify_outcome(exc)
        helper_outcome = control_main._classify_auto_dispatch_outcome(exc)

        self.assertEqual(engine_outcome.verdict, "blocked")
        self.assertEqual(engine_outcome.reason_code, "auto.dispatch.blocked")
        self.assertEqual(
            engine_outcome.recommended_action, "请先补充 Live 可用余额。"
        )
        self.assertTrue(engine_outcome.record_issue)
        # Parity.
        self.assertEqual(engine_outcome.verdict, helper_outcome.verdict)
        self.assertEqual(
            engine_outcome.recommended_action, helper_outcome.recommended_action
        )

    def test_classify_outcome_failed_for_plain_runtime_and_generic_exceptions(self) -> None:
        """Any other ``RuntimeError`` / generic ``Exception`` must surface as
        ``failed`` / ``auto.dispatch.failed`` with the audit prefix on the
        generic-exception branch — pinning the R61 defensive contract through
        the engine."""

        rt_exc = RuntimeError("私有通道暂时不可用，请稍后重试。")
        ve_exc = ValueError("unexpected state machine transition")

        rt_engine = control_main.risk_engine.classify_outcome(rt_exc)
        rt_helper = control_main._classify_auto_dispatch_outcome(rt_exc)
        ve_engine = control_main.risk_engine.classify_outcome(ve_exc)
        ve_helper = control_main._classify_auto_dispatch_outcome(ve_exc)

        self.assertEqual(rt_engine.verdict, "failed")
        self.assertEqual(rt_engine.reason_code, "auto.dispatch.failed")
        self.assertEqual(rt_engine.reason_detail, "私有通道暂时不可用，请稍后重试。")
        self.assertEqual(rt_engine.verdict, rt_helper.verdict)
        self.assertEqual(rt_engine.reason_detail, rt_helper.reason_detail)

        self.assertEqual(ve_engine.verdict, "failed")
        self.assertTrue(ve_engine.reason_detail.startswith("后台自动执行异常："))
        self.assertEqual(ve_engine.verdict, ve_helper.verdict)
        self.assertEqual(ve_engine.reason_detail, ve_helper.reason_detail)


class BacktestEngineRound119Tests(unittest.TestCase):
    """Round 119 — :class:`backtest_engine.BacktestEngine` is the new
    coordinating façade for "everything we can / cannot conclude from a
    given backtest context": the synchronous payload builder plus the
    sample-quality / window-coverage classifiers, the recommendation
    planners, and the review-risk merger.  The helpers used to live on
    ``main.py`` directly; R119 moves the implementations into
    :mod:`backtest_engine` and leaves thin re-export wrappers behind so
    every existing call-site keeps working.

    These tests pin:

    1. The class is constructible with the runtime dependencies wired in
       and exposes the expected public methods.
    2. Each :class:`BacktestEngine` method delegates to the corresponding
       ``main.py`` thin wrapper bit-for-bit (for pure helpers).
    3. The ``main.py`` wrappers themselves delegate to the
       :mod:`backtest_engine` module-level helpers (so the wrappers do
       not contain the actual logic any more).
    4. ``build_payload`` runs end-to-end through the engine and produces
       the same payload as the legacy ``main.build_backtest_payload``
       call-site that ``repo.backtest_runner`` already references.
    """

    def _build_engine(self) -> Any:
        return backtest_engine.BacktestEngine(
            repo=control_main.repo,
            market_data=control_main.market_data,
            resolve_strategy_primary_market=control_main._resolve_strategy_primary_market,
            merge_execution_health_review_risks=control_main._merge_execution_health_review_risks,
        )

    def test_engine_exposes_expected_public_methods(self) -> None:
        engine = self._build_engine()
        for method_name in (
            "build_payload",
            "resolve_decision_readiness",
            "resolve_full_window_recommendation",
            "merge_review_risks",
            "filter_sample_quality_guarded_proposals",
            "extract_safe_sample_validation_payload",
            "build_sample_validation_backtest_payload",
            "build_full_window_backtest_plan",
            "render_sample_validation_action",
            "resolve_history_source_recommendation",
        ):
            self.assertTrue(
                callable(getattr(engine, method_name, None)),
                f"BacktestEngine should expose callable {method_name!r}",
            )

    def test_resolve_decision_readiness_matches_main_wrapper(self) -> None:
        engine = self._build_engine()
        context = {
            "data_range": "最近 180 天",
            "timeframe": "1h",
            "metrics": {"trades": 12},
            "sample_quality": "sufficient",
            "history_source": "exchange_history",
        }
        engine_payload = engine.resolve_decision_readiness(context)
        main_payload = control_main._resolve_backtest_decision_readiness(context)
        self.assertEqual(engine_payload, main_payload)
        self.assertEqual(engine_payload["decision_readiness"], "ready")

    def test_resolve_full_window_recommendation_matches_main_wrapper(self) -> None:
        engine = self._build_engine()
        context = {
            "data_range": "最近 180 天",
            "timeframe": "15m",
            "history_truncated": True,
            "history_gap_reason": "sample_cap",
            "requested_candle_estimate": 30_000,
            "requested_candle_limit": 20_000,
        }
        engine_payload = engine.resolve_full_window_recommendation(context)
        main_payload = control_main._resolve_full_window_recommendation(context)
        self.assertEqual(engine_payload, main_payload)
        self.assertIn("payload", engine_payload)
        self.assertIn("can_cover_full_window", engine_payload)

    def test_build_sample_validation_backtest_payload_matches_main_wrapper(self) -> None:
        engine = self._build_engine()
        engine_payload = engine.build_sample_validation_backtest_payload(
            "最近 90 天",
            "1h",
            prefer_finer_timeframe=True,
        )
        main_payload = control_main._build_sample_validation_backtest_payload(
            "最近 90 天",
            "1h",
            prefer_finer_timeframe=True,
        )
        self.assertEqual(engine_payload, main_payload)
        # Spec: when caller is already on the canonical 180-day window the
        # helper steps the timeframe down; otherwise it expands to 180d.
        self.assertEqual(engine_payload["data_range"], "最近 180 天")

    def test_build_full_window_backtest_plan_matches_main_wrapper(self) -> None:
        engine = self._build_engine()
        engine_plan = engine.build_full_window_backtest_plan("最近 180 天", "1h")
        main_plan = control_main._build_full_window_backtest_plan("最近 180 天", "1h")
        self.assertEqual(engine_plan, main_plan)

    def test_render_sample_validation_action_matches_main_wrapper(self) -> None:
        engine = self._build_engine()
        payload = {"data_range": "最近 180 天", "timeframe": "15m"}
        rendered = engine.render_sample_validation_action(
            "最近 90 天",
            "1h",
            payload,
        )
        main_rendered = control_main._render_sample_validation_action(
            "最近 90 天",
            "1h",
            payload,
        )
        self.assertEqual(rendered, main_rendered)
        self.assertIn("最近 180 天", rendered)
        self.assertIn("15m", rendered)

    def test_resolve_history_source_recommendation_matches_main_wrapper(self) -> None:
        engine = self._build_engine()
        context = {
            "data_range": "最近 180 天",
            "timeframe": "1h",
            "history_source": "market_detail_fallback",
            "history_source_reason": "insufficient_exchange_samples",
        }
