    def test_merge_review_risks_appends_low_sample_warning(self) -> None:
        engine = self._build_engine()
        context = {
            "data_range": "最近 180 天",
            "timeframe": "1h",
            "metrics": {"trades": 2},
            "sample_quality": "low_sample",
            "history_source": "exchange_history",
        }
